CREATE OR ALTER TRIGGER [edfi].[TR_AssessmentItem_ReferentialIdentity]
ON [edfi].[AssessmentItem]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 20;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiAssessmentItem' AS nvarchar(max)) + N'$.assessmentReference.assessmentIdentifier=' + i.[Assessment_AssessmentIdentifier] + N'#' + N'$.assessmentReference.namespace=' + i.[Assessment_Namespace] + N'#' + N'$.identificationCode=' + i.[IdentificationCode]), i.[DocumentId], 20
        FROM inserted i;
    END
    ELSE IF (UPDATE([Assessment_AssessmentIdentifier]) OR UPDATE([Assessment_Namespace]) OR UPDATE([IdentificationCode]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Assessment_AssessmentIdentifier] AS varbinary(max)) <> CAST(d.[Assessment_AssessmentIdentifier] AS varbinary(max)) OR (i.[Assessment_AssessmentIdentifier] IS NULL AND d.[Assessment_AssessmentIdentifier] IS NOT NULL) OR (i.[Assessment_AssessmentIdentifier] IS NOT NULL AND d.[Assessment_AssessmentIdentifier] IS NULL)) OR (CAST(i.[Assessment_Namespace] AS varbinary(max)) <> CAST(d.[Assessment_Namespace] AS varbinary(max)) OR (i.[Assessment_Namespace] IS NULL AND d.[Assessment_Namespace] IS NOT NULL) OR (i.[Assessment_Namespace] IS NOT NULL AND d.[Assessment_Namespace] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(d.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND d.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND d.[IdentificationCode] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 20;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiAssessmentItem' AS nvarchar(max)) + N'$.assessmentReference.assessmentIdentifier=' + i.[Assessment_AssessmentIdentifier] + N'#' + N'$.assessmentReference.namespace=' + i.[Assessment_Namespace] + N'#' + N'$.identificationCode=' + i.[IdentificationCode]), i.[DocumentId], 20
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_AssessmentItem_Stamp]
ON [edfi].[AssessmentItem]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[Assessment_DocumentId] <> del.[Assessment_DocumentId] OR (i.[Assessment_DocumentId] IS NULL AND del.[Assessment_DocumentId] IS NOT NULL) OR (i.[Assessment_DocumentId] IS NOT NULL AND del.[Assessment_DocumentId] IS NULL)) OR (CAST(i.[Assessment_AssessmentIdentifier] AS varbinary(max)) <> CAST(del.[Assessment_AssessmentIdentifier] AS varbinary(max)) OR (i.[Assessment_AssessmentIdentifier] IS NULL AND del.[Assessment_AssessmentIdentifier] IS NOT NULL) OR (i.[Assessment_AssessmentIdentifier] IS NOT NULL AND del.[Assessment_AssessmentIdentifier] IS NULL)) OR (CAST(i.[Assessment_Namespace] AS varbinary(max)) <> CAST(del.[Assessment_Namespace] AS varbinary(max)) OR (i.[Assessment_Namespace] IS NULL AND del.[Assessment_Namespace] IS NOT NULL) OR (i.[Assessment_Namespace] IS NOT NULL AND del.[Assessment_Namespace] IS NULL)) OR (i.[AssessmentItemCategoryDescriptor_DescriptorId] <> del.[AssessmentItemCategoryDescriptor_DescriptorId] OR (i.[AssessmentItemCategoryDescriptor_DescriptorId] IS NULL AND del.[AssessmentItemCategoryDescriptor_DescriptorId] IS NOT NULL) OR (i.[AssessmentItemCategoryDescriptor_DescriptorId] IS NOT NULL AND del.[AssessmentItemCategoryDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[AssessmentItemURI] AS varbinary(max)) <> CAST(del.[AssessmentItemURI] AS varbinary(max)) OR (i.[AssessmentItemURI] IS NULL AND del.[AssessmentItemURI] IS NOT NULL) OR (i.[AssessmentItemURI] IS NOT NULL AND del.[AssessmentItemURI] IS NULL)) OR (CAST(i.[ExpectedTimeAssessed] AS varbinary(max)) <> CAST(del.[ExpectedTimeAssessed] AS varbinary(max)) OR (i.[ExpectedTimeAssessed] IS NULL AND del.[ExpectedTimeAssessed] IS NOT NULL) OR (i.[ExpectedTimeAssessed] IS NOT NULL AND del.[ExpectedTimeAssessed] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(del.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND del.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND del.[IdentificationCode] IS NULL)) OR (CAST(i.[ItemText] AS varbinary(max)) <> CAST(del.[ItemText] AS varbinary(max)) OR (i.[ItemText] IS NULL AND del.[ItemText] IS NOT NULL) OR (i.[ItemText] IS NOT NULL AND del.[ItemText] IS NULL)) OR (i.[MaxRawScore] <> del.[MaxRawScore] OR (i.[MaxRawScore] IS NULL AND del.[MaxRawScore] IS NOT NULL) OR (i.[MaxRawScore] IS NOT NULL AND del.[MaxRawScore] IS NULL)) OR (CAST(i.[Nomenclature] AS varbinary(max)) <> CAST(del.[Nomenclature] AS varbinary(max)) OR (i.[Nomenclature] IS NULL AND del.[Nomenclature] IS NOT NULL) OR (i.[Nomenclature] IS NOT NULL AND del.[Nomenclature] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[AssessmentItem] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[AssessmentItem] (
            [OldAssessment_AssessmentIdentifier],
            [OldAssessment_Namespace],
            [OldIdentificationCode],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Assessment_AssessmentIdentifier],
            del.[Assessment_Namespace],
            del.[IdentificationCode],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Assessment_AssessmentIdentifier] AS varbinary(max)) <> CAST(del.[Assessment_AssessmentIdentifier] AS varbinary(max)) OR (i.[Assessment_AssessmentIdentifier] IS NULL AND del.[Assessment_AssessmentIdentifier] IS NOT NULL) OR (i.[Assessment_AssessmentIdentifier] IS NOT NULL AND del.[Assessment_AssessmentIdentifier] IS NULL)) OR (CAST(i.[Assessment_Namespace] AS varbinary(max)) <> CAST(del.[Assessment_Namespace] AS varbinary(max)) OR (i.[Assessment_Namespace] IS NULL AND del.[Assessment_Namespace] IS NOT NULL) OR (i.[Assessment_Namespace] IS NOT NULL AND del.[Assessment_Namespace] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(del.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND del.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND del.[IdentificationCode] IS NULL));
        INSERT INTO [tracked_changes_edfi].[AssessmentItem] (
            [OldAssessment_AssessmentIdentifier],
            [OldAssessment_Namespace],
            [OldIdentificationCode],
            [NewAssessment_AssessmentIdentifier],
            [NewAssessment_Namespace],
            [NewIdentificationCode],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Assessment_AssessmentIdentifier],
            del.[Assessment_Namespace],
            del.[IdentificationCode],
            i.[Assessment_AssessmentIdentifier],
            i.[Assessment_Namespace],
            i.[IdentificationCode],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

