CREATE OR ALTER TRIGGER [edfi].[TR_BellSchedule_Stamp]
ON [edfi].[BellSchedule]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[School_DocumentId] <> del.[School_DocumentId] OR (i.[School_DocumentId] IS NULL AND del.[School_DocumentId] IS NOT NULL) OR (i.[School_DocumentId] IS NOT NULL AND del.[School_DocumentId] IS NULL)) OR (i.[School_SchoolId] <> del.[School_SchoolId] OR (i.[School_SchoolId] IS NULL AND del.[School_SchoolId] IS NOT NULL) OR (i.[School_SchoolId] IS NOT NULL AND del.[School_SchoolId] IS NULL)) OR (CAST(i.[AlternateDayName] AS varbinary(max)) <> CAST(del.[AlternateDayName] AS varbinary(max)) OR (i.[AlternateDayName] IS NULL AND del.[AlternateDayName] IS NOT NULL) OR (i.[AlternateDayName] IS NOT NULL AND del.[AlternateDayName] IS NULL)) OR (CAST(i.[BellScheduleName] AS varbinary(max)) <> CAST(del.[BellScheduleName] AS varbinary(max)) OR (i.[BellScheduleName] IS NULL AND del.[BellScheduleName] IS NOT NULL) OR (i.[BellScheduleName] IS NOT NULL AND del.[BellScheduleName] IS NULL)) OR (i.[EndTime] <> del.[EndTime] OR (i.[EndTime] IS NULL AND del.[EndTime] IS NOT NULL) OR (i.[EndTime] IS NOT NULL AND del.[EndTime] IS NULL)) OR (i.[StartTime] <> del.[StartTime] OR (i.[StartTime] IS NULL AND del.[StartTime] IS NOT NULL) OR (i.[StartTime] IS NOT NULL AND del.[StartTime] IS NULL)) OR (i.[TotalInstructionalTime] <> del.[TotalInstructionalTime] OR (i.[TotalInstructionalTime] IS NULL AND del.[TotalInstructionalTime] IS NOT NULL) OR (i.[TotalInstructionalTime] IS NOT NULL AND del.[TotalInstructionalTime] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[BellSchedule] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[BellSchedule] (
            [OldBellScheduleName],
            [OldSchool_SchoolId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[BellScheduleName],
            del.[School_SchoolId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[BellScheduleName] AS varbinary(max)) <> CAST(del.[BellScheduleName] AS varbinary(max)) OR (i.[BellScheduleName] IS NULL AND del.[BellScheduleName] IS NOT NULL) OR (i.[BellScheduleName] IS NOT NULL AND del.[BellScheduleName] IS NULL)) OR (i.[School_SchoolId] <> del.[School_SchoolId] OR (i.[School_SchoolId] IS NULL AND del.[School_SchoolId] IS NOT NULL) OR (i.[School_SchoolId] IS NOT NULL AND del.[School_SchoolId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[BellSchedule] (
            [OldBellScheduleName],
            [OldSchool_SchoolId],
            [NewBellScheduleName],
            [NewSchool_SchoolId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[BellScheduleName],
            del.[School_SchoolId],
            i.[BellScheduleName],
            i.[School_SchoolId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

