        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[SchoolYear_DocumentId] <> del.[SchoolYear_DocumentId] OR (i.[SchoolYear_DocumentId] IS NULL AND del.[SchoolYear_DocumentId] IS NOT NULL) OR (i.[SchoolYear_DocumentId] IS NOT NULL AND del.[SchoolYear_DocumentId] IS NULL)) OR (i.[SchoolYear_SchoolYear] <> del.[SchoolYear_SchoolYear] OR (i.[SchoolYear_SchoolYear] IS NULL AND del.[SchoolYear_SchoolYear] IS NOT NULL) OR (i.[SchoolYear_SchoolYear] IS NOT NULL AND del.[SchoolYear_SchoolYear] IS NULL)) OR (i.[School_DocumentId] <> del.[School_DocumentId] OR (i.[School_DocumentId] IS NULL AND del.[School_DocumentId] IS NOT NULL) OR (i.[School_DocumentId] IS NOT NULL AND del.[School_DocumentId] IS NULL)) OR (i.[School_SchoolId] <> del.[School_SchoolId] OR (i.[School_SchoolId] IS NULL AND del.[School_SchoolId] IS NOT NULL) OR (i.[School_SchoolId] IS NOT NULL AND del.[School_SchoolId] IS NULL)) OR (i.[CalendarTypeDescriptor_DescriptorId] <> del.[CalendarTypeDescriptor_DescriptorId] OR (i.[CalendarTypeDescriptor_DescriptorId] IS NULL AND del.[CalendarTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[CalendarTypeDescriptor_DescriptorId] IS NOT NULL AND del.[CalendarTypeDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[CalendarCode] AS varbinary(max)) <> CAST(del.[CalendarCode] AS varbinary(max)) OR (i.[CalendarCode] IS NULL AND del.[CalendarCode] IS NOT NULL) OR (i.[CalendarCode] IS NOT NULL AND del.[CalendarCode] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[Calendar] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[Calendar] (
            [OldCalendarCode],
            [OldSchool_SchoolId],
            [OldSchoolYear_SchoolYear],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[CalendarCode],
            del.[School_SchoolId],
            del.[SchoolYear_SchoolYear],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[CalendarCode] AS varbinary(max)) <> CAST(del.[CalendarCode] AS varbinary(max)) OR (i.[CalendarCode] IS NULL AND del.[CalendarCode] IS NOT NULL) OR (i.[CalendarCode] IS NOT NULL AND del.[CalendarCode] IS NULL)) OR (i.[School_SchoolId] <> del.[School_SchoolId] OR (i.[School_SchoolId] IS NULL AND del.[School_SchoolId] IS NOT NULL) OR (i.[School_SchoolId] IS NOT NULL AND del.[School_SchoolId] IS NULL)) OR (i.[SchoolYear_SchoolYear] <> del.[SchoolYear_SchoolYear] OR (i.[SchoolYear_SchoolYear] IS NULL AND del.[SchoolYear_SchoolYear] IS NOT NULL) OR (i.[SchoolYear_SchoolYear] IS NOT NULL AND del.[SchoolYear_SchoolYear] IS NULL));
        INSERT INTO [tracked_changes_edfi].[Calendar] (
            [OldCalendarCode],
            [OldSchool_SchoolId],
            [OldSchoolYear_SchoolYear],
            [NewCalendarCode],
            [NewSchool_SchoolId],
            [NewSchoolYear_SchoolYear],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[CalendarCode],
            del.[School_SchoolId],
            del.[SchoolYear_SchoolYear],
            i.[CalendarCode],
            i.[School_SchoolId],
            i.[SchoolYear_SchoolYear],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
