        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Cohort_DocumentId] <> del.[Cohort_DocumentId] OR (i.[Cohort_DocumentId] IS NULL AND del.[Cohort_DocumentId] IS NOT NULL) OR (i.[Cohort_DocumentId] IS NOT NULL AND del.[Cohort_DocumentId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[ProgramProgram_DocumentId] <> del.[ProgramProgram_DocumentId] OR (i.[ProgramProgram_DocumentId] IS NULL AND del.[ProgramProgram_DocumentId] IS NOT NULL) OR (i.[ProgramProgram_DocumentId] IS NOT NULL AND del.[ProgramProgram_DocumentId] IS NULL)) OR (i.[ProgramProgram_EducationOrganizationId] <> del.[ProgramProgram_EducationOrganizationId] OR (i.[ProgramProgram_EducationOrganizationId] IS NULL AND del.[ProgramProgram_EducationOrganizationId] IS NOT NULL) OR (i.[ProgramProgram_EducationOrganizationId] IS NOT NULL AND del.[ProgramProgram_EducationOrganizationId] IS NULL)) OR (CAST(i.[ProgramProgram_ProgramName] AS varbinary(max)) <> CAST(del.[ProgramProgram_ProgramName] AS varbinary(max)) OR (i.[ProgramProgram_ProgramName] IS NULL AND del.[ProgramProgram_ProgramName] IS NOT NULL) OR (i.[ProgramProgram_ProgramName] IS NOT NULL AND del.[ProgramProgram_ProgramName] IS NULL)) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] <> del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[Cohort_DocumentId]
    INNER JOIN [edfi].[Cohort] stampTarget ON stampTarget.[DocumentId] = a.[Cohort_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
