        FROM deleted del
        LEFT JOIN inserted i ON i.[CollectionItemId] = del.[CollectionItemId]
        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[CommunityOrganization_DocumentId] <> del.[CommunityOrganization_DocumentId] OR (i.[CommunityOrganization_DocumentId] IS NULL AND del.[CommunityOrganization_DocumentId] IS NOT NULL) OR (i.[CommunityOrganization_DocumentId] IS NOT NULL AND del.[CommunityOrganization_DocumentId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] <> del.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] OR (i.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] IS NULL AND del.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] IS NOT NULL AND del.[InstitutionTelephoneNumberTypeDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[TelephoneNumber] AS varbinary(max)) <> CAST(del.[TelephoneNumber] AS varbinary(max)) OR (i.[TelephoneNumber] IS NULL AND del.[TelephoneNumber] IS NOT NULL) OR (i.[TelephoneNumber] IS NOT NULL AND del.[TelephoneNumber] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[CommunityOrganization_DocumentId]
    INNER JOIN [edfi].[CommunityOrganization] stampTarget ON stampTarget.[DocumentId] = a.[CommunityOrganization_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[CommunityOrganization] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
