CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_AbstractIdentity]
ON [edfi].[CommunityProvider]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        UPDATE t
        SET t.[EducationOrganizationId] = s.[CommunityProviderId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN inserted s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[CommunityProviderId], N'Ed-Fi:CommunityProvider'
        FROM inserted s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
    ELSE IF (UPDATE([CommunityProviderId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[CommunityProviderId] <> d.[CommunityProviderId] OR (i.[CommunityProviderId] IS NULL AND d.[CommunityProviderId] IS NOT NULL) OR (i.[CommunityProviderId] IS NOT NULL AND d.[CommunityProviderId] IS NULL));
        UPDATE t
        SET t.[EducationOrganizationId] = s.[CommunityProviderId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[CommunityProviderId], N'Ed-Fi:CommunityProvider'
        FROM (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_AuthHierarchy_Delete]
ON [edfi].[CommunityProvider]
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], old.[CommunityProviderId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[CommunityOrganization_CommunityOrganizationId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL
            ) AS d1
            CROSS JOIN
            (
                SELECT old.[CommunityProviderId], tuples.[TargetEducationOrganizationId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[CommunityProviderId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[CommunityProviderId] = d2.[CommunityProviderId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    DELETE tuples
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
        INNER JOIN deleted old
            ON tuples.[SourceEducationOrganizationId] = old.[CommunityProviderId]
            AND tuples.[TargetEducationOrganizationId] = old.[CommunityProviderId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_AuthHierarchy_Insert]
ON [edfi].[CommunityProvider]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT new.[CommunityProviderId], new.[CommunityProviderId]
    FROM inserted new;

    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
    FROM (
        SELECT tuples.[SourceEducationOrganizationId], new.[CommunityProviderId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[CommunityOrganization_CommunityOrganizationId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL
    ) AS sources
    CROSS JOIN
    (
        SELECT new.[CommunityProviderId], tuples.[TargetEducationOrganizationId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[CommunityProviderId] = tuples.[SourceEducationOrganizationId]
    ) AS targets
    WHERE sources.[CommunityProviderId] = targets.[CommunityProviderId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_AuthHierarchy_Update]
ON [edfi].[CommunityProvider]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], new.[CommunityProviderId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[CommunityProviderId] = new.[CommunityProviderId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[CommunityOrganization_CommunityOrganizationId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL
                    AND (new.[CommunityOrganization_CommunityOrganizationId] IS NULL OR old.[CommunityOrganization_CommunityOrganizationId] <> new.[CommunityOrganization_CommunityOrganizationId])

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[CommunityProviderId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[CommunityOrganization_CommunityOrganizationId] = tuples.[TargetEducationOrganizationId]
            ) AS d1
            CROSS JOIN
            (
                SELECT new.[CommunityProviderId], tuples.[TargetEducationOrganizationId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[CommunityProviderId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[CommunityProviderId] = d2.[CommunityProviderId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    MERGE INTO [auth].[EducationOrganizationIdToEducationOrganizationId] target
    USING (
        SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
        FROM (
            SELECT tuples.[SourceEducationOrganizationId], new.[CommunityProviderId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[CommunityProviderId] = old.[CommunityProviderId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[CommunityOrganization_CommunityOrganizationId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[CommunityOrganization_CommunityOrganizationId] IS NULL AND new.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL)
                OR old.[CommunityOrganization_CommunityOrganizationId] <> new.[CommunityOrganization_CommunityOrganizationId]
        ) AS sources
        CROSS JOIN
        (
            SELECT new.[CommunityProviderId], tuples.[TargetEducationOrganizationId]
            FROM inserted new
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[CommunityProviderId] = tuples.[SourceEducationOrganizationId]
        ) AS targets
        WHERE sources.[CommunityProviderId] = targets.[CommunityProviderId]
    ) AS source
        ON target.[SourceEducationOrganizationId] = source.[SourceEducationOrganizationId]
        AND target.[TargetEducationOrganizationId] = source.[TargetEducationOrganizationId]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
        VALUES (source.[SourceEducationOrganizationId], source.[TargetEducationOrganizationId]);
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_ReferentialIdentity]
ON [edfi].[CommunityProvider]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 51;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiCommunityProvider' AS nvarchar(max)) + N'$.communityProviderId=' + CAST(i.[CommunityProviderId] AS nvarchar(max))), i.[DocumentId], 51
        FROM inserted i;
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[CommunityProviderId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i;
    END
    ELSE IF (UPDATE([CommunityProviderId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[CommunityProviderId] <> d.[CommunityProviderId] OR (i.[CommunityProviderId] IS NULL AND d.[CommunityProviderId] IS NOT NULL) OR (i.[CommunityProviderId] IS NOT NULL AND d.[CommunityProviderId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 51;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiCommunityProvider' AS nvarchar(max)) + N'$.communityProviderId=' + CAST(i.[CommunityProviderId] AS nvarchar(max))), i.[DocumentId], 51
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[CommunityProviderId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_CommunityProvider_Stamp]
ON [edfi].[CommunityProvider]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[CommunityOrganization_DocumentId] <> del.[CommunityOrganization_DocumentId] OR (i.[CommunityOrganization_DocumentId] IS NULL AND del.[CommunityOrganization_DocumentId] IS NOT NULL) OR (i.[CommunityOrganization_DocumentId] IS NOT NULL AND del.[CommunityOrganization_DocumentId] IS NULL)) OR (i.[CommunityOrganization_CommunityOrganizationId] <> del.[CommunityOrganization_CommunityOrganizationId] OR (i.[CommunityOrganization_CommunityOrganizationId] IS NULL AND del.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL) OR (i.[CommunityOrganization_CommunityOrganizationId] IS NOT NULL AND del.[CommunityOrganization_CommunityOrganizationId] IS NULL)) OR (i.[OperationalStatusDescriptor_DescriptorId] <> del.[OperationalStatusDescriptor_DescriptorId] OR (i.[OperationalStatusDescriptor_DescriptorId] IS NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NULL)) OR (i.[ProviderCategoryDescriptor_DescriptorId] <> del.[ProviderCategoryDescriptor_DescriptorId] OR (i.[ProviderCategoryDescriptor_DescriptorId] IS NULL AND del.[ProviderCategoryDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProviderCategoryDescriptor_DescriptorId] IS NOT NULL AND del.[ProviderCategoryDescriptor_DescriptorId] IS NULL)) OR (i.[ProviderProfitabilityDescriptor_DescriptorId] <> del.[ProviderProfitabilityDescriptor_DescriptorId] OR (i.[ProviderProfitabilityDescriptor_DescriptorId] IS NULL AND del.[ProviderProfitabilityDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProviderProfitabilityDescriptor_DescriptorId] IS NOT NULL AND del.[ProviderProfitabilityDescriptor_DescriptorId] IS NULL)) OR (i.[ProviderStatusDescriptor_DescriptorId] <> del.[ProviderStatusDescriptor_DescriptorId] OR (i.[ProviderStatusDescriptor_DescriptorId] IS NULL AND del.[ProviderStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProviderStatusDescriptor_DescriptorId] IS NOT NULL AND del.[ProviderStatusDescriptor_DescriptorId] IS NULL)) OR (i.[CommunityProviderId] <> del.[CommunityProviderId] OR (i.[CommunityProviderId] IS NULL AND del.[CommunityProviderId] IS NOT NULL) OR (i.[CommunityProviderId] IS NOT NULL AND del.[CommunityProviderId] IS NULL)) OR (i.[LicenseExemptIndicator] <> del.[LicenseExemptIndicator] OR (i.[LicenseExemptIndicator] IS NULL AND del.[LicenseExemptIndicator] IS NOT NULL) OR (i.[LicenseExemptIndicator] IS NOT NULL AND del.[LicenseExemptIndicator] IS NULL)) OR (CAST(i.[NameOfInstitution] AS varbinary(max)) <> CAST(del.[NameOfInstitution] AS varbinary(max)) OR (i.[NameOfInstitution] IS NULL AND del.[NameOfInstitution] IS NOT NULL) OR (i.[NameOfInstitution] IS NOT NULL AND del.[NameOfInstitution] IS NULL)) OR (i.[SchoolIndicator] <> del.[SchoolIndicator] OR (i.[SchoolIndicator] IS NULL AND del.[SchoolIndicator] IS NOT NULL) OR (i.[SchoolIndicator] IS NOT NULL AND del.[SchoolIndicator] IS NULL)) OR (CAST(i.[ShortNameOfInstitution] AS varbinary(max)) <> CAST(del.[ShortNameOfInstitution] AS varbinary(max)) OR (i.[ShortNameOfInstitution] IS NULL AND del.[ShortNameOfInstitution] IS NOT NULL) OR (i.[ShortNameOfInstitution] IS NOT NULL AND del.[ShortNameOfInstitution] IS NULL)) OR (CAST(i.[WebSite] AS varbinary(max)) <> CAST(del.[WebSite] AS varbinary(max)) OR (i.[WebSite] IS NULL AND del.[WebSite] IS NOT NULL) OR (i.[WebSite] IS NOT NULL AND del.[WebSite] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[CommunityProvider] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[CommunityProvider] (
            [OldCommunityProviderId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[CommunityProviderId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND (UPDATE([CommunityProviderId]))
    BEGIN
