CREATE OR ALTER TRIGGER [edfi].[TR_CompetencyObjective_Stamp]
ON [edfi].[CompetencyObjective]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[EducationOrganization_DocumentId] <> del.[EducationOrganization_DocumentId] OR (i.[EducationOrganization_DocumentId] IS NULL AND del.[EducationOrganization_DocumentId] IS NOT NULL) OR (i.[EducationOrganization_DocumentId] IS NOT NULL AND del.[EducationOrganization_DocumentId] IS NULL)) OR (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] <> del.[ObjectiveGradeLevelDescriptor_DescriptorId] OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NULL AND del.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NOT NULL) OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NOT NULL AND del.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[CompetencyObjectiveId] AS varbinary(max)) <> CAST(del.[CompetencyObjectiveId] AS varbinary(max)) OR (i.[CompetencyObjectiveId] IS NULL AND del.[CompetencyObjectiveId] IS NOT NULL) OR (i.[CompetencyObjectiveId] IS NOT NULL AND del.[CompetencyObjectiveId] IS NULL)) OR (CAST(i.[Description] AS varbinary(max)) <> CAST(del.[Description] AS varbinary(max)) OR (i.[Description] IS NULL AND del.[Description] IS NOT NULL) OR (i.[Description] IS NOT NULL AND del.[Description] IS NULL)) OR (CAST(i.[Objective] AS varbinary(max)) <> CAST(del.[Objective] AS varbinary(max)) OR (i.[Objective] IS NULL AND del.[Objective] IS NOT NULL) OR (i.[Objective] IS NOT NULL AND del.[Objective] IS NULL)) OR (CAST(i.[SuccessCriteria] AS varbinary(max)) <> CAST(del.[SuccessCriteria] AS varbinary(max)) OR (i.[SuccessCriteria] IS NULL AND del.[SuccessCriteria] IS NOT NULL) OR (i.[SuccessCriteria] IS NOT NULL AND del.[SuccessCriteria] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[CompetencyObjective] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[CompetencyObjective] (
            [OldEducationOrganization_EducationOrganizationId],
            [OldObjective],
            [OldObjectiveGradeLevelDescriptor_Namespace],
            [OldObjectiveGradeLevelDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[EducationOrganization_EducationOrganizationId],
            del.[Objective],
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ObjectiveGradeLevelDescriptor_DescriptorId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (CAST(i.[Objective] AS varbinary(max)) <> CAST(del.[Objective] AS varbinary(max)) OR (i.[Objective] IS NULL AND del.[Objective] IS NOT NULL) OR (i.[Objective] IS NOT NULL AND del.[Objective] IS NULL)) OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] <> del.[ObjectiveGradeLevelDescriptor_DescriptorId] OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NULL AND del.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NOT NULL) OR (i.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NOT NULL AND del.[ObjectiveGradeLevelDescriptor_DescriptorId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[CompetencyObjective] (
            [OldEducationOrganization_EducationOrganizationId],
            [OldObjective],
            [OldObjectiveGradeLevelDescriptor_Namespace],
            [OldObjectiveGradeLevelDescriptor_CodeValue],
            [NewEducationOrganization_EducationOrganizationId],
            [NewObjective],
            [NewObjectiveGradeLevelDescriptor_Namespace],
            [NewObjectiveGradeLevelDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[EducationOrganization_EducationOrganizationId],
            del.[Objective],
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            i.[EducationOrganization_EducationOrganizationId],
            i.[Objective],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ObjectiveGradeLevelDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj0 ON newDj0.[DocumentId] = i.[ObjectiveGradeLevelDescriptor_DescriptorId];
    END
END;
