        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[CourseTranscript] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[CourseTranscript] (
            [OldCourseAttemptResultDescriptor_Namespace],
            [OldCourseAttemptResultDescriptor_CodeValue],
            [OldCourseCourse_CourseCode],
            [OldCourseCourse_EducationOrganizationId],
            [OldStudentAcademicRecord_EducationOrganizationId],
            [OldStudentAcademicRecord_SchoolYear],
            [OldStudentAcademicRecord_StudentUniqueId],
            [OldStudentAcademicRecord_TermDescriptor_Namespace],
            [OldStudentAcademicRecord_TermDescriptor_CodeValue],
            [OldStudentAcademicRecord_Student_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[CourseCourse_CourseCode],
            del.[CourseCourse_EducationOrganizationId],
            del.[StudentAcademicRecord_EducationOrganizationId],
            del.[StudentAcademicRecord_SchoolYear],
            del.[StudentAcademicRecord_StudentUniqueId],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            oldPj0s1.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[CourseAttemptResultDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj1 ON oldDj1.[DocumentId] = del.[StudentAcademicRecord_TermDescriptor_DescriptorId]
