        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (CAST(i.[MappedNamespace] AS varbinary(max)) <> CAST(del.[MappedNamespace] AS varbinary(max)) OR (i.[MappedNamespace] IS NULL AND del.[MappedNamespace] IS NOT NULL) OR (i.[MappedNamespace] IS NOT NULL AND del.[MappedNamespace] IS NULL)) OR (CAST(i.[MappedValue] AS varbinary(max)) <> CAST(del.[MappedValue] AS varbinary(max)) OR (i.[MappedValue] IS NULL AND del.[MappedValue] IS NOT NULL) OR (i.[MappedValue] IS NOT NULL AND del.[MappedValue] IS NULL)) OR (CAST(i.[Namespace] AS varbinary(max)) <> CAST(del.[Namespace] AS varbinary(max)) OR (i.[Namespace] IS NULL AND del.[Namespace] IS NOT NULL) OR (i.[Namespace] IS NOT NULL AND del.[Namespace] IS NULL)) OR (CAST(i.[Value] AS varbinary(max)) <> CAST(del.[Value] AS varbinary(max)) OR (i.[Value] IS NULL AND del.[Value] IS NOT NULL) OR (i.[Value] IS NOT NULL AND del.[Value] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[DescriptorMapping] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[DescriptorMapping] (
            [OldMappedNamespace],
            [OldMappedValue],
            [OldNamespace],
            [OldValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[MappedNamespace],
            del.[MappedValue],
            del.[Namespace],
            del.[Value],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[MappedNamespace] AS varbinary(max)) <> CAST(del.[MappedNamespace] AS varbinary(max)) OR (i.[MappedNamespace] IS NULL AND del.[MappedNamespace] IS NOT NULL) OR (i.[MappedNamespace] IS NOT NULL AND del.[MappedNamespace] IS NULL)) OR (CAST(i.[MappedValue] AS varbinary(max)) <> CAST(del.[MappedValue] AS varbinary(max)) OR (i.[MappedValue] IS NULL AND del.[MappedValue] IS NOT NULL) OR (i.[MappedValue] IS NOT NULL AND del.[MappedValue] IS NULL)) OR (CAST(i.[Namespace] AS varbinary(max)) <> CAST(del.[Namespace] AS varbinary(max)) OR (i.[Namespace] IS NULL AND del.[Namespace] IS NOT NULL) OR (i.[Namespace] IS NOT NULL AND del.[Namespace] IS NULL)) OR (CAST(i.[Value] AS varbinary(max)) <> CAST(del.[Value] AS varbinary(max)) OR (i.[Value] IS NULL AND del.[Value] IS NOT NULL) OR (i.[Value] IS NOT NULL AND del.[Value] IS NULL));
        INSERT INTO [tracked_changes_edfi].[DescriptorMapping] (
            [OldMappedNamespace],
            [OldMappedValue],
            [OldNamespace],
            [OldValue],
            [NewMappedNamespace],
            [NewMappedValue],
            [NewNamespace],
            [NewValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[MappedNamespace],
            del.[MappedValue],
            del.[Namespace],
            del.[Value],
            i.[MappedNamespace],
            i.[MappedValue],
            i.[Namespace],
            i.[Value],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
