 AS varbinary(max)) <> CAST(del.[AddressLine4] AS varbinary(max)) OR (i.[AddressLine4] IS NULL AND del.[AddressLine4] IS NOT NULL) OR (i.[AddressLine4] IS NOT NULL AND del.[AddressLine4] IS NULL)) OR (i.[BeginDate] <> del.[BeginDate] OR (i.[BeginDate] IS NULL AND del.[BeginDate] IS NOT NULL) OR (i.[BeginDate] IS NOT NULL AND del.[BeginDate] IS NULL)) OR (i.[EndDate] <> del.[EndDate] OR (i.[EndDate] IS NULL AND del.[EndDate] IS NOT NULL) OR (i.[EndDate] IS NOT NULL AND del.[EndDate] IS NULL)) OR (CAST(i.[Latitude] AS varbinary(max)) <> CAST(del.[Latitude] AS varbinary(max)) OR (i.[Latitude] IS NULL AND del.[Latitude] IS NOT NULL) OR (i.[Latitude] IS NOT NULL AND del.[Latitude] IS NULL)) OR (CAST(i.[Longitude] AS varbinary(max)) <> CAST(del.[Longitude] AS varbinary(max)) OR (i.[Longitude] IS NULL AND del.[Longitude] IS NOT NULL) OR (i.[Longitude] IS NOT NULL AND del.[Longitude] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[EducationOrganizationNetwork_DocumentId]
    INNER JOIN [edfi].[EducationOrganizationNetwork] stampTarget ON stampTarget.[DocumentId] = a.[EducationOrganizationNetwork_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[EducationOrganizationNetwork] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
