CREATE OR ALTER TRIGGER [edfi].[TR_EducationOrganizationPeerAssociation_ReferentialIdentity]
ON [edfi].[EducationOrganizationPeerAssociation]
AFTER INSERT, UPDATE
AS
BEGIN
