CREATE OR ALTER TRIGGER [edfi].[TR_EducationOrganizationPeerAssociation_Stamp]
ON [edfi].[EducationOrganizationPeerAssociation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[EducationOrganization_DocumentId] <> del.[EducationOrganization_DocumentId] OR (i.[EducationOrganization_DocumentId] IS NULL AND del.[EducationOrganization_DocumentId] IS NOT NULL) OR (i.[EducationOrganization_DocumentId] IS NOT NULL AND del.[EducationOrganization_DocumentId] IS NULL)) OR (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (i.[PeerEducationOrganization_DocumentId] <> del.[PeerEducationOrganization_DocumentId] OR (i.[PeerEducationOrganization_DocumentId] IS NULL AND del.[PeerEducationOrganization_DocumentId] IS NOT NULL) OR (i.[PeerEducationOrganization_DocumentId] IS NOT NULL AND del.[PeerEducationOrganization_DocumentId] IS NULL)) OR (i.[PeerEducationOrganization_EducationOrganizationId] <> del.[PeerEducationOrganization_EducationOrganizationId] OR (i.[PeerEducationOrganization_EducationOrganizationId] IS NULL AND del.[PeerEducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[PeerEducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[PeerEducationOrganization_EducationOrganizationId] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[EducationOrganizationPeerAssociation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[EducationOrganizationPeerAssociation] (
            [OldEducationOrganization_EducationOrganizationId],
            [OldPeerEducationOrganization_EducationOrganizationId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[EducationOrganization_EducationOrganizationId],
            del.[PeerEducationOrganization_EducationOrganizationId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (i.[PeerEducationOrganization_EducationOrganizationId] <> del.[PeerEducationOrganization_EducationOrganizationId] OR (i.[PeerEducationOrganization_EducationOrganizationId] IS NULL AND del.[PeerEducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[PeerEducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[PeerEducationOrganization_EducationOrganizationId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[EducationOrganizationPeerAssociation] (
            [OldEducationOrganization_EducationOrganizationId],
            [OldPeerEducationOrganization_EducationOrganizationId],
            [NewEducationOrganization_EducationOrganizationId],
            [NewPeerEducationOrganization_EducationOrganizationId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[EducationOrganization_EducationOrganizationId],
            del.[PeerEducationOrganization_EducationOrganizationId],
            i.[EducationOrganization_EducationOrganizationId],
            i.[PeerEducationOrganization_EducationOrganizationId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_EducationServiceCenter_AbstractIdentity]
ON [edfi].[EducationServiceCenter]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        UPDATE t
        SET t.[EducationOrganizationId] = s.[EducationServiceCenterId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN inserted s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[EducationServiceCenterId], N'Ed-Fi:EducationServiceCenter'
        FROM inserted s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
    ELSE IF (UPDATE([EducationServiceCenterId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[EducationServiceCenterId] <> d.[EducationServiceCenterId] OR (i.[EducationServiceCenterId] IS NULL AND d.[EducationServiceCenterId] IS NOT NULL) OR (i.[EducationServiceCenterId] IS NOT NULL AND d.[EducationServiceCenterId] IS NULL));
        UPDATE t
        SET t.[EducationOrganizationId] = s.[EducationServiceCenterId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[EducationServiceCenterId], N'Ed-Fi:EducationServiceCenter'
        FROM (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_EducationServiceCenter_AuthHierarchy_Delete]
ON [edfi].[EducationServiceCenter]
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], old.[EducationServiceCenterId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
            ) AS d1
            CROSS JOIN
            (
                SELECT old.[EducationServiceCenterId], tuples.[TargetEducationOrganizationId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[EducationServiceCenterId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[EducationServiceCenterId] = d2.[EducationServiceCenterId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    DELETE tuples
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
        INNER JOIN deleted old
            ON tuples.[SourceEducationOrganizationId] = old.[EducationServiceCenterId]
            AND tuples.[TargetEducationOrganizationId] = old.[EducationServiceCenterId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_EducationServiceCenter_AuthHierarchy_Insert]
ON [edfi].[EducationServiceCenter]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT new.[EducationServiceCenterId], new.[EducationServiceCenterId]
    FROM inserted new;

    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
    FROM (
        SELECT tuples.[SourceEducationOrganizationId], new.[EducationServiceCenterId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
    ) AS sources
    CROSS JOIN
    (
        SELECT new.[EducationServiceCenterId], tuples.[TargetEducationOrganizationId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[EducationServiceCenterId] = tuples.[SourceEducationOrganizationId]
    ) AS targets
    WHERE sources.[EducationServiceCenterId] = targets.[EducationServiceCenterId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_EducationServiceCenter_AuthHierarchy_Update]
ON [edfi].[EducationServiceCenter]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], new.[EducationServiceCenterId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[EducationServiceCenterId] = new.[EducationServiceCenterId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
                    AND (new.[StateEducationAgency_StateEducationAgencyId] IS NULL OR old.[StateEducationAgency_StateEducationAgencyId] <> new.[StateEducationAgency_StateEducationAgencyId])

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[EducationServiceCenterId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
            ) AS d1
            CROSS JOIN
            (
                SELECT new.[EducationServiceCenterId], tuples.[TargetEducationOrganizationId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[EducationServiceCenterId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[EducationServiceCenterId] = d2.[EducationServiceCenterId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    MERGE INTO [auth].[EducationOrganizationIdToEducationOrganizationId] target
    USING (
        SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
        FROM (
            SELECT tuples.[SourceEducationOrganizationId], new.[EducationServiceCenterId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[EducationServiceCenterId] = old.[EducationServiceCenterId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[StateEducationAgency_StateEducationAgencyId] IS NULL AND new.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL)
                OR old.[StateEducationAgency_StateEducationAgencyId] <> new.[StateEducationAgency_StateEducationAgencyId]
        ) AS sources
        CROSS JOIN
        (
            SELECT new.[EducationServiceCenterId], tuples.[TargetEducationOrganizationId]
            FROM inserted new
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[EducationServiceCenterId] = tuples.[SourceEducationOrganizationId]
        ) AS targets
        WHERE sources.[EducationServiceCenterId] = targets.[EducationServiceCenterId]
    ) AS source
        ON target.[SourceEducationOrganizationId] = source.[SourceEducationOrganizationId]
        AND target.[TargetEducationOrganizationId] = source.[TargetEducationOrganizationId]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
        VALUES (source.[SourceEducationOrganizationId], source.[TargetEducationOrganizationId]);
END;
GO

