        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[FunctionDimension_DocumentId] <> del.[FunctionDimension_DocumentId] OR (i.[FunctionDimension_DocumentId] IS NULL AND del.[FunctionDimension_DocumentId] IS NOT NULL) OR (i.[FunctionDimension_DocumentId] IS NOT NULL AND del.[FunctionDimension_DocumentId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[ReportingTagDescriptor_DescriptorId] <> del.[ReportingTagDescriptor_DescriptorId] OR (i.[ReportingTagDescriptor_DescriptorId] IS NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NOT NULL) OR (i.[ReportingTagDescriptor_DescriptorId] IS NOT NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[FunctionDimension_DocumentId]
    INNER JOIN [edfi].[FunctionDimension] stampTarget ON stampTarget.[DocumentId] = a.[FunctionDimension_DocumentId];
