        LEFT JOIN deleted del ON del.[CollectionItemId] = i.[CollectionItemId]
        WHERE del.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[GradebookEntry_DocumentId] <> del.[GradebookEntry_DocumentId] OR (i.[GradebookEntry_DocumentId] IS NULL AND del.[GradebookEntry_DocumentId] IS NOT NULL) OR (i.[GradebookEntry_DocumentId] IS NOT NULL AND del.[GradebookEntry_DocumentId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[LearningStandard_DocumentId] <> del.[LearningStandard_DocumentId] OR (i.[LearningStandard_DocumentId] IS NULL AND del.[LearningStandard_DocumentId] IS NOT NULL) OR (i.[LearningStandard_DocumentId] IS NOT NULL AND del.[LearningStandard_DocumentId] IS NULL)) OR (CAST(i.[LearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[LearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[LearningStandard_LearningStandardId] IS NULL AND del.[LearningStandard_LearningStandardId] IS NOT NULL) OR (i.[LearningStandard_LearningStandardId] IS NOT NULL AND del.[LearningStandard_LearningStandardId] IS NULL))
        UNION
        SELECT del.[GradebookEntry_DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[CollectionItemId] = del.[CollectionItemId]
        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[GradebookEntry_DocumentId] <> del.[GradebookEntry_DocumentId] OR (i.[GradebookEntry_DocumentId] IS NULL AND del.[GradebookEntry_DocumentId] IS NOT NULL) OR (i.[GradebookEntry_DocumentId] IS NOT NULL AND del.[GradebookEntry_DocumentId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[LearningStandard_DocumentId] <> del.[LearningStandard_DocumentId] OR (i.[LearningStandard_DocumentId] IS NULL AND del.[LearningStandard_DocumentId] IS NOT NULL) OR (i.[LearningStandard_DocumentId] IS NOT NULL AND del.[LearningStandard_DocumentId] IS NULL)) OR (CAST(i.[LearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[LearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[LearningStandard_LearningStandardId] IS NULL AND del.[LearningStandard_LearningStandardId] IS NOT NULL) OR (i.[LearningStandard_LearningStandardId] IS NOT NULL AND del.[LearningStandard_LearningStandardId] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[GradebookEntry_DocumentId]
    INNER JOIN [edfi].[GradebookEntry] stampTarget ON stampTarget.[DocumentId] = a.[GradebookEntry_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[GradebookEntry] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
