CREATE OR ALTER TRIGGER [edfi].[TR_LearningStandardEquivalenceAssociation_ReferentialIdentity]
ON [edfi].[LearningStandardEquivalenceAssociation]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 157;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLearningStandardEquivalenceAssociation' AS nvarchar(max)) + N'$.namespace=' + i.[Namespace] + N'#' + N'$.sourceLearningStandardReference.learningStandardId=' + i.[SourceLearningStandard_LearningStandardId] + N'#' + N'$.targetLearningStandardReference.learningStandardId=' + i.[TargetLearningStandard_LearningStandardId]), i.[DocumentId], 157
        FROM inserted i;
    END
    ELSE IF (UPDATE([Namespace]) OR UPDATE([SourceLearningStandard_LearningStandardId]) OR UPDATE([TargetLearningStandard_LearningStandardId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Namespace] AS varbinary(max)) <> CAST(d.[Namespace] AS varbinary(max)) OR (i.[Namespace] IS NULL AND d.[Namespace] IS NOT NULL) OR (i.[Namespace] IS NOT NULL AND d.[Namespace] IS NULL)) OR (CAST(i.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(d.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[SourceLearningStandard_LearningStandardId] IS NULL AND d.[SourceLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[SourceLearningStandard_LearningStandardId] IS NOT NULL AND d.[SourceLearningStandard_LearningStandardId] IS NULL)) OR (CAST(i.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(d.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[TargetLearningStandard_LearningStandardId] IS NULL AND d.[TargetLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[TargetLearningStandard_LearningStandardId] IS NOT NULL AND d.[TargetLearningStandard_LearningStandardId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 157;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLearningStandardEquivalenceAssociation' AS nvarchar(max)) + N'$.namespace=' + i.[Namespace] + N'#' + N'$.sourceLearningStandardReference.learningStandardId=' + i.[SourceLearningStandard_LearningStandardId] + N'#' + N'$.targetLearningStandardReference.learningStandardId=' + i.[TargetLearningStandard_LearningStandardId]), i.[DocumentId], 157
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LearningStandardEquivalenceAssociation_Stamp]
ON [edfi].[LearningStandardEquivalenceAssociation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[SourceLearningStandard_DocumentId] <> del.[SourceLearningStandard_DocumentId] OR (i.[SourceLearningStandard_DocumentId] IS NULL AND del.[SourceLearningStandard_DocumentId] IS NOT NULL) OR (i.[SourceLearningStandard_DocumentId] IS NOT NULL AND del.[SourceLearningStandard_DocumentId] IS NULL)) OR (CAST(i.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[SourceLearningStandard_LearningStandardId] IS NULL AND del.[SourceLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[SourceLearningStandard_LearningStandardId] IS NOT NULL AND del.[SourceLearningStandard_LearningStandardId] IS NULL)) OR (i.[TargetLearningStandard_DocumentId] <> del.[TargetLearningStandard_DocumentId] OR (i.[TargetLearningStandard_DocumentId] IS NULL AND del.[TargetLearningStandard_DocumentId] IS NOT NULL) OR (i.[TargetLearningStandard_DocumentId] IS NOT NULL AND del.[TargetLearningStandard_DocumentId] IS NULL)) OR (CAST(i.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[TargetLearningStandard_LearningStandardId] IS NULL AND del.[TargetLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[TargetLearningStandard_LearningStandardId] IS NOT NULL AND del.[TargetLearningStandard_LearningStandardId] IS NULL)) OR (i.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] <> del.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] OR (i.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] IS NULL AND del.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] IS NOT NULL) OR (i.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] IS NOT NULL AND del.[LearningStandardEquivalenceStrengthDescriptor_DescriptorId] IS NULL)) OR (i.[EffectiveDate] <> del.[EffectiveDate] OR (i.[EffectiveDate] IS NULL AND del.[EffectiveDate] IS NOT NULL) OR (i.[EffectiveDate] IS NOT NULL AND del.[EffectiveDate] IS NULL)) OR (CAST(i.[LearningStandardEquivalenceStrengthDescription] AS varbinary(max)) <> CAST(del.[LearningStandardEquivalenceStrengthDescription] AS varbinary(max)) OR (i.[LearningStandardEquivalenceStrengthDescription] IS NULL AND del.[LearningStandardEquivalenceStrengthDescription] IS NOT NULL) OR (i.[LearningStandardEquivalenceStrengthDescription] IS NOT NULL AND del.[LearningStandardEquivalenceStrengthDescription] IS NULL)) OR (CAST(i.[Namespace] AS varbinary(max)) <> CAST(del.[Namespace] AS varbinary(max)) OR (i.[Namespace] IS NULL AND del.[Namespace] IS NOT NULL) OR (i.[Namespace] IS NOT NULL AND del.[Namespace] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[LearningStandardEquivalenceAssociation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[LearningStandardEquivalenceAssociation] (
            [OldNamespace],
            [OldSourceLearningStandard_LearningStandardId],
            [OldTargetLearningStandard_LearningStandardId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Namespace],
            del.[SourceLearningStandard_LearningStandardId],
            del.[TargetLearningStandard_LearningStandardId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Namespace] AS varbinary(max)) <> CAST(del.[Namespace] AS varbinary(max)) OR (i.[Namespace] IS NULL AND del.[Namespace] IS NOT NULL) OR (i.[Namespace] IS NOT NULL AND del.[Namespace] IS NULL)) OR (CAST(i.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[SourceLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[SourceLearningStandard_LearningStandardId] IS NULL AND del.[SourceLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[SourceLearningStandard_LearningStandardId] IS NOT NULL AND del.[SourceLearningStandard_LearningStandardId] IS NULL)) OR (CAST(i.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) <> CAST(del.[TargetLearningStandard_LearningStandardId] AS varbinary(max)) OR (i.[TargetLearningStandard_LearningStandardId] IS NULL AND del.[TargetLearningStandard_LearningStandardId] IS NOT NULL) OR (i.[TargetLearningStandard_LearningStandardId] IS NOT NULL AND del.[TargetLearningStandard_LearningStandardId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[LearningStandardEquivalenceAssociation] (
            [OldNamespace],
            [OldSourceLearningStandard_LearningStandardId],
            [OldTargetLearningStandard_LearningStandardId],
            [NewNamespace],
            [NewSourceLearningStandard_LearningStandardId],
            [NewTargetLearningStandard_LearningStandardId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Namespace],
            del.[SourceLearningStandard_LearningStandardId],
            del.[TargetLearningStandard_LearningStandardId],
            i.[Namespace],
            i.[SourceLearningStandard_LearningStandardId],
            i.[TargetLearningStandard_LearningStandardId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

