    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[LocalBudget] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[LocalBudget] (
            [OldAsOfDate],
            [OldLocalAccount_AccountIdentifier],
            [OldLocalAccount_EducationOrganizationId],
            [OldLocalAccount_FiscalYear],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AsOfDate],
            del.[LocalAccount_AccountIdentifier],
            del.[LocalAccount_EducationOrganizationId],
            del.[LocalAccount_FiscalYear],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[AsOfDate] <> del.[AsOfDate] OR (i.[AsOfDate] IS NULL AND del.[AsOfDate] IS NOT NULL) OR (i.[AsOfDate] IS NOT NULL AND del.[AsOfDate] IS NULL)) OR (CAST(i.[LocalAccount_AccountIdentifier] AS varbinary(max)) <> CAST(del.[LocalAccount_AccountIdentifier] AS varbinary(max)) OR (i.[LocalAccount_AccountIdentifier] IS NULL AND del.[LocalAccount_AccountIdentifier] IS NOT NULL) OR (i.[LocalAccount_AccountIdentifier] IS NOT NULL AND del.[LocalAccount_AccountIdentifier] IS NULL)) OR (i.[LocalAccount_EducationOrganizationId] <> del.[LocalAccount_EducationOrganizationId] OR (i.[LocalAccount_EducationOrganizationId] IS NULL AND del.[LocalAccount_EducationOrganizationId] IS NOT NULL) OR (i.[LocalAccount_EducationOrganizationId] IS NOT NULL AND del.[LocalAccount_EducationOrganizationId] IS NULL)) OR (i.[LocalAccount_FiscalYear] <> del.[LocalAccount_FiscalYear] OR (i.[LocalAccount_FiscalYear] IS NULL AND del.[LocalAccount_FiscalYear] IS NOT NULL) OR (i.[LocalAccount_FiscalYear] IS NOT NULL AND del.[LocalAccount_FiscalYear] IS NULL));
        INSERT INTO [tracked_changes_edfi].[LocalBudget] (
            [OldAsOfDate],
            [OldLocalAccount_AccountIdentifier],
            [OldLocalAccount_EducationOrganizationId],
            [OldLocalAccount_FiscalYear],
            [NewAsOfDate],
            [NewLocalAccount_AccountIdentifier],
            [NewLocalAccount_EducationOrganizationId],
            [NewLocalAccount_FiscalYear],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AsOfDate],
            del.[LocalAccount_AccountIdentifier],
            del.[LocalAccount_EducationOrganizationId],
            del.[LocalAccount_FiscalYear],
            i.[AsOfDate],
            i.[LocalAccount_AccountIdentifier],
            i.[LocalAccount_EducationOrganizationId],
            i.[LocalAccount_FiscalYear],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalContractedStaff_ReferentialIdentity]
ON [edfi].[LocalContractedStaff]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 167;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLocalContractedStaff' AS nvarchar(max)) + N'$.asOfDate=' + CONVERT(nvarchar(10), i.[AsOfDate], 23) + N'#' + N'$.localAccountReference.accountIdentifier=' + i.[LocalAccount_AccountIdentifier] + N'#' + N'$.localAccountReference.educationOrganizationId=' + CAST(i.[LocalAccount_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.localAccountReference.fiscalYear=' + CAST(i.[LocalAccount_FiscalYear] AS nvarchar(max)) + N'#' + N'$.staffReference.staffUniqueId=' + i.[Staff_StaffUniqueId]), i.[DocumentId], 167
        FROM inserted i;
    END
    ELSE IF (UPDATE([AsOfDate]) OR UPDATE([LocalAccount_AccountIdentifier]) OR UPDATE([LocalAccount_EducationOrganizationId]) OR UPDATE([LocalAccount_FiscalYear]) OR UPDATE([Staff_StaffUniqueId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[AsOfDate] <> d.[AsOfDate] OR (i.[AsOfDate] IS NULL AND d.[AsOfDate] IS NOT NULL) OR (i.[AsOfDate] IS NOT NULL AND d.[AsOfDate] IS NULL)) OR (CAST(i.[LocalAccount_AccountIdentifier] AS varbinary(max)) <> CAST(d.[LocalAccount_AccountIdentifier] AS varbinary(max)) OR (i.[LocalAccount_AccountIdentifier] IS NULL AND d.[LocalAccount_AccountIdentifier] IS NOT NULL) OR (i.[LocalAccount_AccountIdentifier] IS NOT NULL AND d.[LocalAccount_AccountIdentifier] IS NULL)) OR (i.[LocalAccount_EducationOrganizationId] <> d.[LocalAccount_EducationOrganizationId] OR (i.[LocalAccount_EducationOrganizationId] IS NULL AND d.[LocalAccount_EducationOrganizationId] IS NOT NULL) OR (i.[LocalAccount_EducationOrganizationId] IS NOT NULL AND d.[LocalAccount_EducationOrganizationId] IS NULL)) OR (i.[LocalAccount_FiscalYear] <> d.[LocalAccount_FiscalYear] OR (i.[LocalAccount_FiscalYear] IS NULL AND d.[LocalAccount_FiscalYear] IS NOT NULL) OR (i.[LocalAccount_FiscalYear] IS NOT NULL AND d.[LocalAccount_FiscalYear] IS NULL)) OR (CAST(i.[Staff_StaffUniqueId] AS varbinary(max)) <> CAST(d.[Staff_StaffUniqueId] AS varbinary(max)) OR (i.[Staff_StaffUniqueId] IS NULL AND d.[Staff_StaffUniqueId] IS NOT NULL) OR (i.[Staff_StaffUniqueId] IS NOT NULL AND d.[Staff_StaffUniqueId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 167;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLocalContractedStaff' AS nvarchar(max)) + N'$.asOfDate=' + CONVERT(nvarchar(10), i.[AsOfDate], 23) + N'#' + N'$.localAccountReference.accountIdentifier=' + i.[LocalAccount_AccountIdentifier] + N'#' + N'$.localAccountReference.educationOrganizationId=' + CAST(i.[LocalAccount_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.localAccountReference.fiscalYear=' + CAST(i.[LocalAccount_FiscalYear] AS nvarchar(max)) + N'#' + N'$.staffReference.staffUniqueId=' + i.[Staff_StaffUniqueId]), i.[DocumentId], 167
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalContractedStaff_Stamp]
ON [edfi].[LocalContractedStaff]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[LocalAccount_DocumentId] <> del.[LocalAccount_DocumentId] OR (i.[LocalAccount_DocumentId] IS NULL AND del.[LocalAccount_DocumentId] IS NOT NULL) OR (i.[LocalAccount_DocumentId] IS NOT NULL AND del.[LocalAccount_DocumentId] IS NULL)) OR (CAST(i.[LocalAccount_AccountIdentifier] AS varbinary(max)) <> CAST(del.[LocalAccount_AccountIdentifier] AS varbinary(max)) OR (i.[LocalAccount_AccountIdentifier] IS NULL AND del.[LocalAccount_AccountIdentifier] IS NOT NULL) OR (i.[LocalAccount_AccountIdentifier] IS NOT NULL AND del.[LocalAccount_AccountIdentifier] IS NULL)) OR (i.[LocalAccount_EducationOrganizationId] <> del.[LocalAccount_EducationOrganizationId] OR (i.[LocalAccount_EducationOrganizationId] IS NULL AND del.[LocalAccount_EducationOrganizationId] IS NOT NULL) OR (i.[LocalAccount_EducationOrganizationId] IS NOT NULL AND del.[LocalAccount_EducationOrganizationId] IS NULL)) OR (i.[LocalAccount_FiscalYear] <> del.[LocalAccount_FiscalYear] OR (i.[LocalAccount_FiscalYear] IS NULL AND del.[LocalAccount_FiscalYear] IS NOT NULL) OR (i.[LocalAccount_FiscalYear] IS NOT NULL AND del.[LocalAccount_FiscalYear] IS NULL)) OR (i.[Staff_DocumentId] <> del.[Staff_DocumentId] OR (i.[Staff_DocumentId] IS NULL AND del.[Staff_DocumentId] IS NOT NULL) OR (i.[Staff_DocumentId] IS NOT NULL AND del.[Staff_DocumentId] IS NULL)) OR (CAST(i.[Staff_StaffUniqueId] AS varbinary(max)) <> CAST(del.[Staff_StaffUniqueId] AS varbinary(max)) OR (i.[Staff_StaffUniqueId] IS NULL AND del.[Staff_StaffUniqueId] IS NOT NULL) OR (i.[Staff_StaffUniqueId] IS NOT NULL AND del.[Staff_StaffUniqueId] IS NULL)) OR (i.[FinancialCollectionDescriptor_DescriptorId] <> del.[FinancialCollectionDescriptor_DescriptorId] OR (i.[FinancialCollectionDescriptor_DescriptorId] IS NULL AND del.[FinancialCollectionDescriptor_DescriptorId] IS NOT NULL) OR (i.[FinancialCollectionDescriptor_DescriptorId] IS NOT NULL AND del.[FinancialCollectionDescriptor_DescriptorId] IS NULL)) OR (i.[Amount] <> del.[Amount] OR (i.[Amount] IS NULL AND del.[Amount] IS NOT NULL) OR (i.[Amount] IS NOT NULL AND del.[Amount] IS NULL)) OR (i.[AsOfDate] <> del.[AsOfDate] OR (i.[AsOfDate] IS NULL AND del.[AsOfDate] IS NOT NULL) OR (i.[AsOfDate] IS NOT NULL AND del.[AsOfDate] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[LocalContractedStaff] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[LocalContractedStaff] (
            [OldAsOfDate],
            [OldLocalAccount_AccountIdentifier],
            [OldLocalAccount_EducationOrganizationId],
            [OldLocalAccount_FiscalYear],
            [OldStaff_StaffUniqueId],
            [OldStaff_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AsOfDate],
            del.[LocalAccount_AccountIdentifier],
            del.[LocalAccount_EducationOrganizationId],
            del.[LocalAccount_FiscalYear],
            del.[Staff_StaffUniqueId],
            oldPj0s0.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [edfi].[Staff] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Staff_DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[AsOfDate] <> del.[AsOfDate] OR (i.[AsOfDate] IS NULL AND del.[AsOfDate] IS NOT NULL) OR (i.[AsOfDate] IS NOT NULL AND del.[AsOfDate] IS NULL)) OR (CAST(i.[LocalAccount_AccountIdentifier] AS varbinary(max)) <> CAST(del.[LocalAccount_AccountIdentifier] AS varbinary(max)) OR (i.[LocalAccount_AccountIdentifier] IS NULL AND del.[LocalAccount_AccountIdentifier] IS NOT NULL) OR (i.[LocalAccount_AccountIdentifier] IS NOT NULL AND del.[LocalAccount_AccountIdentifier] IS NULL)) OR (i.[LocalAccount_EducationOrganizationId] <> del.[LocalAccount_EducationOrganizationId] OR (i.[LocalAccount_EducationOrganizationId] IS NULL AND del.[LocalAccount_EducationOrganizationId] IS NOT NULL) OR (i.[LocalAccount_EducationOrganizationId] IS NOT NULL AND del.[LocalAccount_EducationOrganizationId] IS NULL)) OR (i.[LocalAccount_FiscalYear] <> del.[LocalAccount_FiscalYear] OR (i.[LocalAccount_FiscalYear] IS NULL AND del.[LocalAccount_FiscalYear] IS NOT NULL) OR (i.[LocalAccount_FiscalYear] IS NOT NULL AND del.[LocalAccount_FiscalYear] IS NULL)) OR (CAST(i.[Staff_StaffUniqueId] AS varbinary(max)) <> CAST(del.[Staff_StaffUniqueId] AS varbinary(max)) OR (i.[Staff_StaffUniqueId] IS NULL AND del.[Staff_StaffUniqueId] IS NOT NULL) OR (i.[Staff_StaffUniqueId] IS NOT NULL AND del.[Staff_StaffUniqueId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[LocalContractedStaff] (
            [OldAsOfDate],
            [OldLocalAccount_AccountIdentifier],
            [OldLocalAccount_EducationOrganizationId],
            [OldLocalAccount_FiscalYear],
            [OldStaff_StaffUniqueId],
            [OldStaff_DocumentId],
            [NewAsOfDate],
            [NewLocalAccount_AccountIdentifier],
            [NewLocalAccount_EducationOrganizationId],
            [NewLocalAccount_FiscalYear],
            [NewStaff_StaffUniqueId],
            [NewStaff_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AsOfDate],
            del.[LocalAccount_AccountIdentifier],
            del.[LocalAccount_EducationOrganizationId],
            del.[LocalAccount_FiscalYear],
            del.[Staff_StaffUniqueId],
            oldPj0s0.[DocumentId],
            i.[AsOfDate],
            i.[LocalAccount_AccountIdentifier],
            i.[LocalAccount_EducationOrganizationId],
            i.[LocalAccount_FiscalYear],
            i.[Staff_StaffUniqueId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [edfi].[Staff] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Staff_DocumentId]
        INNER JOIN [edfi].[Staff] newPj0s0 ON newPj0s0.[DocumentId] = i.[Staff_DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_AbstractIdentity]
ON [edfi].[LocalEducationAgency]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        UPDATE t
        SET t.[EducationOrganizationId] = s.[LocalEducationAgencyId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN inserted s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[LocalEducationAgencyId], N'Ed-Fi:LocalEducationAgency'
        FROM inserted s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
    ELSE IF (UPDATE([LocalEducationAgencyId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[LocalEducationAgencyId] <> d.[LocalEducationAgencyId] OR (i.[LocalEducationAgencyId] IS NULL AND d.[LocalEducationAgencyId] IS NOT NULL) OR (i.[LocalEducationAgencyId] IS NOT NULL AND d.[LocalEducationAgencyId] IS NULL));
        UPDATE t
        SET t.[EducationOrganizationId] = s.[LocalEducationAgencyId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[LocalEducationAgencyId], N'Ed-Fi:LocalEducationAgency'
        FROM (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_AuthHierarchy_Delete]
ON [edfi].[LocalEducationAgency]
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], old.[LocalEducationAgencyId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[EducationServiceCenter_EducationServiceCenterId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL

                UNION

                SELECT tuples.[SourceEducationOrganizationId], old.[LocalEducationAgencyId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[ParentLocalEducationAgency_LocalEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL

                UNION

                SELECT tuples.[SourceEducationOrganizationId], old.[LocalEducationAgencyId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
            ) AS d1
            CROSS JOIN
            (
                SELECT old.[LocalEducationAgencyId], tuples.[TargetEducationOrganizationId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[LocalEducationAgencyId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[LocalEducationAgencyId] = d2.[LocalEducationAgencyId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    DELETE tuples
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
        INNER JOIN deleted old
            ON tuples.[SourceEducationOrganizationId] = old.[LocalEducationAgencyId]
            AND tuples.[TargetEducationOrganizationId] = old.[LocalEducationAgencyId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_AuthHierarchy_Insert]
ON [edfi].[LocalEducationAgency]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT new.[LocalEducationAgencyId], new.[LocalEducationAgencyId]
    FROM inserted new;

    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
    FROM (
        SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[EducationServiceCenter_EducationServiceCenterId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL

        UNION

        SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[ParentLocalEducationAgency_LocalEducationAgencyId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL

        UNION

        SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
    ) AS sources
    CROSS JOIN
    (
        SELECT new.[LocalEducationAgencyId], tuples.[TargetEducationOrganizationId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[LocalEducationAgencyId] = tuples.[SourceEducationOrganizationId]
    ) AS targets
    WHERE sources.[LocalEducationAgencyId] = targets.[LocalEducationAgencyId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_AuthHierarchy_Update]
ON [edfi].[LocalEducationAgency]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[LocalEducationAgencyId] = new.[LocalEducationAgencyId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[EducationServiceCenter_EducationServiceCenterId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL
                    AND (new.[EducationServiceCenter_EducationServiceCenterId] IS NULL OR old.[EducationServiceCenter_EducationServiceCenterId] <> new.[EducationServiceCenter_EducationServiceCenterId])

                UNION

                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[LocalEducationAgencyId] = new.[LocalEducationAgencyId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[ParentLocalEducationAgency_LocalEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL
                    AND (new.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NULL OR old.[ParentLocalEducationAgency_LocalEducationAgencyId] <> new.[ParentLocalEducationAgency_LocalEducationAgencyId])

                UNION

                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[LocalEducationAgencyId] = new.[LocalEducationAgencyId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL
                    AND (new.[StateEducationAgency_StateEducationAgencyId] IS NULL OR old.[StateEducationAgency_StateEducationAgencyId] <> new.[StateEducationAgency_StateEducationAgencyId])

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[EducationServiceCenter_EducationServiceCenterId] = tuples.[TargetEducationOrganizationId]

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[ParentLocalEducationAgency_LocalEducationAgencyId] = tuples.[TargetEducationOrganizationId]

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
            ) AS d1
            CROSS JOIN
            (
                SELECT new.[LocalEducationAgencyId], tuples.[TargetEducationOrganizationId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[LocalEducationAgencyId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[LocalEducationAgencyId] = d2.[LocalEducationAgencyId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    MERGE INTO [auth].[EducationOrganizationIdToEducationOrganizationId] target
    USING (
        SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
        FROM (
            SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[LocalEducationAgencyId] = old.[LocalEducationAgencyId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[EducationServiceCenter_EducationServiceCenterId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[EducationServiceCenter_EducationServiceCenterId] IS NULL AND new.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL)
                OR old.[EducationServiceCenter_EducationServiceCenterId] <> new.[EducationServiceCenter_EducationServiceCenterId]

            UNION

            SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[LocalEducationAgencyId] = old.[LocalEducationAgencyId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[ParentLocalEducationAgency_LocalEducationAgencyId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NULL AND new.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL)
                OR old.[ParentLocalEducationAgency_LocalEducationAgencyId] <> new.[ParentLocalEducationAgency_LocalEducationAgencyId]

            UNION

            SELECT tuples.[SourceEducationOrganizationId], new.[LocalEducationAgencyId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[LocalEducationAgencyId] = old.[LocalEducationAgencyId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[StateEducationAgency_StateEducationAgencyId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[StateEducationAgency_StateEducationAgencyId] IS NULL AND new.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL)
                OR old.[StateEducationAgency_StateEducationAgencyId] <> new.[StateEducationAgency_StateEducationAgencyId]
        ) AS sources
        CROSS JOIN
        (
            SELECT new.[LocalEducationAgencyId], tuples.[TargetEducationOrganizationId]
            FROM inserted new
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[LocalEducationAgencyId] = tuples.[SourceEducationOrganizationId]
        ) AS targets
        WHERE sources.[LocalEducationAgencyId] = targets.[LocalEducationAgencyId]
    ) AS source
        ON target.[SourceEducationOrganizationId] = source.[SourceEducationOrganizationId]
        AND target.[TargetEducationOrganizationId] = source.[TargetEducationOrganizationId]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
        VALUES (source.[SourceEducationOrganizationId], source.[TargetEducationOrganizationId]);
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_ReferentialIdentity]
ON [edfi].[LocalEducationAgency]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 168;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLocalEducationAgency' AS nvarchar(max)) + N'$.localEducationAgencyId=' + CAST(i.[LocalEducationAgencyId] AS nvarchar(max))), i.[DocumentId], 168
        FROM inserted i;
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[LocalEducationAgencyId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i;
    END
    ELSE IF (UPDATE([LocalEducationAgencyId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[LocalEducationAgencyId] <> d.[LocalEducationAgencyId] OR (i.[LocalEducationAgencyId] IS NULL AND d.[LocalEducationAgencyId] IS NOT NULL) OR (i.[LocalEducationAgencyId] IS NOT NULL AND d.[LocalEducationAgencyId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 168;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiLocalEducationAgency' AS nvarchar(max)) + N'$.localEducationAgencyId=' + CAST(i.[LocalEducationAgencyId] AS nvarchar(max))), i.[DocumentId], 168
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[LocalEducationAgencyId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_LocalEducationAgency_Stamp]
ON [edfi].[LocalEducationAgency]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[EducationServiceCenter_DocumentId] <> del.[EducationServiceCenter_DocumentId] OR (i.[EducationServiceCenter_DocumentId] IS NULL AND del.[EducationServiceCenter_DocumentId] IS NOT NULL) OR (i.[EducationServiceCenter_DocumentId] IS NOT NULL AND del.[EducationServiceCenter_DocumentId] IS NULL)) OR (i.[EducationServiceCenter_EducationServiceCenterId] <> del.[EducationServiceCenter_EducationServiceCenterId] OR (i.[EducationServiceCenter_EducationServiceCenterId] IS NULL AND del.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL) OR (i.[EducationServiceCenter_EducationServiceCenterId] IS NOT NULL AND del.[EducationServiceCenter_EducationServiceCenterId] IS NULL)) OR (i.[ParentLocalEducationAgency_DocumentId] <> del.[ParentLocalEducationAgency_DocumentId] OR (i.[ParentLocalEducationAgency_DocumentId] IS NULL AND del.[ParentLocalEducationAgency_DocumentId] IS NOT NULL) OR (i.[ParentLocalEducationAgency_DocumentId] IS NOT NULL AND del.[ParentLocalEducationAgency_DocumentId] IS NULL)) OR (i.[ParentLocalEducationAgency_LocalEducationAgencyId] <> del.[ParentLocalEducationAgency_LocalEducationAgencyId] OR (i.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NULL AND del.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL) OR (i.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NOT NULL AND del.[ParentLocalEducationAgency_LocalEducationAgencyId] IS NULL)) OR (i.[StateEducationAgency_DocumentId] <> del.[StateEducationAgency_DocumentId] OR (i.[StateEducationAgency_DocumentId] IS NULL AND del.[StateEducationAgency_DocumentId] IS NOT NULL) OR (i.[StateEducationAgency_DocumentId] IS NOT NULL AND del.[StateEducationAgency_DocumentId] IS NULL)) OR (i.[StateEducationAgency_StateEducationAgencyId] <> del.[StateEducationAgency_StateEducationAgencyId] OR (i.[StateEducationAgency_StateEducationAgencyId] IS NULL AND del.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL) OR (i.[StateEducationAgency_StateEducationAgencyId] IS NOT NULL AND del.[StateEducationAgency_StateEducationAgencyId] IS NULL)) OR (i.[CharterStatusDescriptor_DescriptorId] <> del.[CharterStatusDescriptor_DescriptorId] OR (i.[CharterStatusDescriptor_DescriptorId] IS NULL AND del.[CharterStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[CharterStatusDescriptor_DescriptorId] IS NOT NULL AND del.[CharterStatusDescriptor_DescriptorId] IS NULL)) OR (i.[LocalEducationAgencyCategoryDescriptor_DescriptorId] <> del.[LocalEducationAgencyCategoryDescriptor_DescriptorId] OR (i.[LocalEducationAgencyCategoryDescriptor_DescriptorId] IS NULL AND del.[LocalEducationAgencyCategoryDescriptor_DescriptorId] IS NOT NULL) OR (i.[LocalEducationAgencyCategoryDescriptor_DescriptorId] IS NOT NULL AND del.[LocalEducationAgencyCategoryDescriptor_DescriptorId] IS NULL)) OR (i.[OperationalStatusDescriptor_DescriptorId] <> del.[OperationalStatusDescriptor_DescriptorId] OR (i.[OperationalStatusDescriptor_DescriptorId] IS NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NULL)) OR (i.[LocalEducationAgencyId] <> del.[LocalEducationAgencyId] OR (i.[LocalEducationAgencyId] IS NULL AND del.[LocalEducationAgencyId] IS NOT NULL) OR (i.[LocalEducationAgencyId] IS NOT NULL AND del.[LocalEducationAgencyId] IS NULL)) OR (CAST(i.[NameOfInstitution] AS varbinary(max)) <> CAST(del.[NameOfInstitution] AS varbinary(max)) OR (i.[NameOfInstitution] IS NULL AND del.[NameOfInstitution] IS NOT NULL) OR (i.[NameOfInstitution] IS NOT NULL AND del.[NameOfInstitution] IS NULL)) OR (CAST(i.[ShortNameOfInstitution] AS varbinary(max)) <> CAST(del.[ShortNameOfInstitution] AS varbinary(max)) OR (i.[ShortNameOfInstitution] IS NULL AND del.[ShortNameOfInstitution] IS NOT NULL) OR (i.[ShortNameOfInstitution] IS NOT NULL AND del.[ShortNameOfInstitution] IS NULL)) OR (CAST(i.[WebSite] AS varbinary(max)) <> CAST(del.[WebSite] AS varbinary(max)) OR (i.[WebSite] IS NULL AND del.[WebSite] IS NOT NULL) OR (i.[WebSite] IS NOT NULL AND del.[WebSite] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[LocalEducationAgency] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[LocalEducationAgency] (
            [OldLocalEducationAgencyId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[LocalEducationAgencyId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND (UPDATE([LocalEducationAgencyId]))
    BEGIN
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[LocalEducationAgencyId] <> del.[LocalEducationAgencyId] OR (i.[LocalEducationAgencyId] IS NULL AND del.[LocalEducationAgencyId] IS NOT NULL) OR (i.[LocalEducationAgencyId] IS NOT NULL AND del.[LocalEducationAgencyId] IS NULL));
    END
END;
GO

