CREATE OR ALTER TRIGGER [edfi].[TR_ObjectiveAssessment_ReferentialIdentity]
ON [edfi].[ObjectiveAssessment]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 185;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiObjectiveAssessment' AS nvarchar(max)) + N'$.assessmentReference.assessmentIdentifier=' + i.[Assessment_AssessmentIdentifier] + N'#' + N'$.assessmentReference.namespace=' + i.[Assessment_Namespace] + N'#' + N'$.identificationCode=' + i.[IdentificationCode]), i.[DocumentId], 185
        FROM inserted i;
    END
    ELSE IF (UPDATE([AssessmentIdentifier_Unified]) OR UPDATE([Namespace_Unified]) OR UPDATE([IdentificationCode]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[AssessmentIdentifier_Unified] AS varbinary(max)) <> CAST(d.[AssessmentIdentifier_Unified] AS varbinary(max)) OR (i.[AssessmentIdentifier_Unified] IS NULL AND d.[AssessmentIdentifier_Unified] IS NOT NULL) OR (i.[AssessmentIdentifier_Unified] IS NOT NULL AND d.[AssessmentIdentifier_Unified] IS NULL)) OR (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(d.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND d.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND d.[Namespace_Unified] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(d.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND d.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND d.[IdentificationCode] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 185;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiObjectiveAssessment' AS nvarchar(max)) + N'$.assessmentReference.assessmentIdentifier=' + i.[Assessment_AssessmentIdentifier] + N'#' + N'$.assessmentReference.namespace=' + i.[Assessment_Namespace] + N'#' + N'$.identificationCode=' + i.[IdentificationCode]), i.[DocumentId], 185
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_ObjectiveAssessment_Stamp]
ON [edfi].[ObjectiveAssessment]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (CAST(i.[AssessmentIdentifier_Unified] AS varbinary(max)) <> CAST(del.[AssessmentIdentifier_Unified] AS varbinary(max)) OR (i.[AssessmentIdentifier_Unified] IS NULL AND del.[AssessmentIdentifier_Unified] IS NOT NULL) OR (i.[AssessmentIdentifier_Unified] IS NOT NULL AND del.[AssessmentIdentifier_Unified] IS NULL)) OR (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(del.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND del.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND del.[Namespace_Unified] IS NULL)) OR (i.[Assessment_DocumentId] <> del.[Assessment_DocumentId] OR (i.[Assessment_DocumentId] IS NULL AND del.[Assessment_DocumentId] IS NOT NULL) OR (i.[Assessment_DocumentId] IS NOT NULL AND del.[Assessment_DocumentId] IS NULL)) OR (i.[ParentObjectiveAssessment_DocumentId] <> del.[ParentObjectiveAssessment_DocumentId] OR (i.[ParentObjectiveAssessment_DocumentId] IS NULL AND del.[ParentObjectiveAssessment_DocumentId] IS NOT NULL) OR (i.[ParentObjectiveAssessment_DocumentId] IS NOT NULL AND del.[ParentObjectiveAssessment_DocumentId] IS NULL)) OR (CAST(i.[ParentObjectiveAssessment_IdentificationCode] AS varbinary(max)) <> CAST(del.[ParentObjectiveAssessment_IdentificationCode] AS varbinary(max)) OR (i.[ParentObjectiveAssessment_IdentificationCode] IS NULL AND del.[ParentObjectiveAssessment_IdentificationCode] IS NOT NULL) OR (i.[ParentObjectiveAssessment_IdentificationCode] IS NOT NULL AND del.[ParentObjectiveAssessment_IdentificationCode] IS NULL)) OR (i.[AcademicSubjectDescriptor_DescriptorId] <> del.[AcademicSubjectDescriptor_DescriptorId] OR (i.[AcademicSubjectDescriptor_DescriptorId] IS NULL AND del.[AcademicSubjectDescriptor_DescriptorId] IS NOT NULL) OR (i.[AcademicSubjectDescriptor_DescriptorId] IS NOT NULL AND del.[AcademicSubjectDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[Description] AS varbinary(max)) <> CAST(del.[Description] AS varbinary(max)) OR (i.[Description] IS NULL AND del.[Description] IS NOT NULL) OR (i.[Description] IS NOT NULL AND del.[Description] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(del.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND del.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND del.[IdentificationCode] IS NULL)) OR (i.[MaxRawScore] <> del.[MaxRawScore] OR (i.[MaxRawScore] IS NULL AND del.[MaxRawScore] IS NOT NULL) OR (i.[MaxRawScore] IS NOT NULL AND del.[MaxRawScore] IS NULL)) OR (CAST(i.[Nomenclature] AS varbinary(max)) <> CAST(del.[Nomenclature] AS varbinary(max)) OR (i.[Nomenclature] IS NULL AND del.[Nomenclature] IS NOT NULL) OR (i.[Nomenclature] IS NOT NULL AND del.[Nomenclature] IS NULL)) OR (i.[PercentOfAssessment] <> del.[PercentOfAssessment] OR (i.[PercentOfAssessment] IS NULL AND del.[PercentOfAssessment] IS NOT NULL) OR (i.[PercentOfAssessment] IS NOT NULL AND del.[PercentOfAssessment] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[ObjectiveAssessment] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[ObjectiveAssessment] (
            [OldAssessmentIdentifier_Unified],
            [OldNamespace_Unified],
            [OldIdentificationCode],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AssessmentIdentifier_Unified],
            del.[Namespace_Unified],
            del.[IdentificationCode],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[AssessmentIdentifier_Unified] AS varbinary(max)) <> CAST(del.[AssessmentIdentifier_Unified] AS varbinary(max)) OR (i.[AssessmentIdentifier_Unified] IS NULL AND del.[AssessmentIdentifier_Unified] IS NOT NULL) OR (i.[AssessmentIdentifier_Unified] IS NOT NULL AND del.[AssessmentIdentifier_Unified] IS NULL)) OR (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(del.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND del.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND del.[Namespace_Unified] IS NULL)) OR (CAST(i.[IdentificationCode] AS varbinary(max)) <> CAST(del.[IdentificationCode] AS varbinary(max)) OR (i.[IdentificationCode] IS NULL AND del.[IdentificationCode] IS NOT NULL) OR (i.[IdentificationCode] IS NOT NULL AND del.[IdentificationCode] IS NULL));
        INSERT INTO [tracked_changes_edfi].[ObjectiveAssessment] (
            [OldAssessmentIdentifier_Unified],
            [OldNamespace_Unified],
            [OldIdentificationCode],
            [NewAssessmentIdentifier_Unified],
            [NewNamespace_Unified],
            [NewIdentificationCode],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[AssessmentIdentifier_Unified],
            del.[Namespace_Unified],
            del.[IdentificationCode],
            i.[AssessmentIdentifier_Unified],
            i.[Namespace_Unified],
            i.[IdentificationCode],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

