CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_AbstractIdentity]
ON [edfi].[OrganizationDepartment]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        UPDATE t
        SET t.[EducationOrganizationId] = s.[OrganizationDepartmentId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN inserted s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[OrganizationDepartmentId], N'Ed-Fi:OrganizationDepartment'
        FROM inserted s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
    ELSE IF (UPDATE([OrganizationDepartmentId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[OrganizationDepartmentId] <> d.[OrganizationDepartmentId] OR (i.[OrganizationDepartmentId] IS NULL AND d.[OrganizationDepartmentId] IS NOT NULL) OR (i.[OrganizationDepartmentId] IS NOT NULL AND d.[OrganizationDepartmentId] IS NULL));
        UPDATE t
        SET t.[EducationOrganizationId] = s.[OrganizationDepartmentId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[OrganizationDepartmentId], N'Ed-Fi:OrganizationDepartment'
        FROM (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_AuthHierarchy_Delete]
ON [edfi].[OrganizationDepartment]
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], old.[OrganizationDepartmentId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[ParentEducationOrganization_EducationOrganizationId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL
            ) AS d1
            CROSS JOIN
            (
                SELECT old.[OrganizationDepartmentId], tuples.[TargetEducationOrganizationId]
                FROM deleted old
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[OrganizationDepartmentId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[OrganizationDepartmentId] = d2.[OrganizationDepartmentId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    DELETE tuples
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
        INNER JOIN deleted old
            ON tuples.[SourceEducationOrganizationId] = old.[OrganizationDepartmentId]
            AND tuples.[TargetEducationOrganizationId] = old.[OrganizationDepartmentId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_AuthHierarchy_Insert]
ON [edfi].[OrganizationDepartment]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT new.[OrganizationDepartmentId], new.[OrganizationDepartmentId]
    FROM inserted new;

    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
    FROM (
        SELECT tuples.[SourceEducationOrganizationId], new.[OrganizationDepartmentId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[ParentEducationOrganization_EducationOrganizationId] = tuples.[TargetEducationOrganizationId]
        WHERE new.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL
    ) AS sources
    CROSS JOIN
    (
        SELECT new.[OrganizationDepartmentId], tuples.[TargetEducationOrganizationId]
        FROM inserted new
            INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                ON new.[OrganizationDepartmentId] = tuples.[SourceEducationOrganizationId]
    ) AS targets
    WHERE sources.[OrganizationDepartmentId] = targets.[OrganizationDepartmentId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_AuthHierarchy_Update]
ON [edfi].[OrganizationDepartment]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tbd
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tbd
        INNER JOIN (
            SELECT d1.[SourceEducationOrganizationId], d2.[TargetEducationOrganizationId]
            FROM (
                SELECT tuples.[SourceEducationOrganizationId], new.[OrganizationDepartmentId]
                FROM inserted new
                    INNER JOIN deleted old
                        ON old.[OrganizationDepartmentId] = new.[OrganizationDepartmentId]
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON old.[ParentEducationOrganization_EducationOrganizationId] = tuples.[TargetEducationOrganizationId]
                WHERE old.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL
                    AND (new.[ParentEducationOrganization_EducationOrganizationId] IS NULL OR old.[ParentEducationOrganization_EducationOrganizationId] <> new.[ParentEducationOrganization_EducationOrganizationId])

                EXCEPT

                SELECT tuples.[SourceEducationOrganizationId], new.[OrganizationDepartmentId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[ParentEducationOrganization_EducationOrganizationId] = tuples.[TargetEducationOrganizationId]
            ) AS d1
            CROSS JOIN
            (
                SELECT new.[OrganizationDepartmentId], tuples.[TargetEducationOrganizationId]
                FROM inserted new
                    INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                        ON new.[OrganizationDepartmentId] = tuples.[SourceEducationOrganizationId]
            ) AS d2
            WHERE d1.[OrganizationDepartmentId] = d2.[OrganizationDepartmentId]
        ) AS cj
            ON tbd.[SourceEducationOrganizationId] = cj.[SourceEducationOrganizationId]
            AND tbd.[TargetEducationOrganizationId] = cj.[TargetEducationOrganizationId];

    MERGE INTO [auth].[EducationOrganizationIdToEducationOrganizationId] target
    USING (
        SELECT sources.[SourceEducationOrganizationId], targets.[TargetEducationOrganizationId]
        FROM (
            SELECT tuples.[SourceEducationOrganizationId], new.[OrganizationDepartmentId]
            FROM inserted new
                INNER JOIN deleted old
                    ON new.[OrganizationDepartmentId] = old.[OrganizationDepartmentId]
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[ParentEducationOrganization_EducationOrganizationId] = tuples.[TargetEducationOrganizationId]
            WHERE (old.[ParentEducationOrganization_EducationOrganizationId] IS NULL AND new.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL)
                OR old.[ParentEducationOrganization_EducationOrganizationId] <> new.[ParentEducationOrganization_EducationOrganizationId]
        ) AS sources
        CROSS JOIN
        (
            SELECT new.[OrganizationDepartmentId], tuples.[TargetEducationOrganizationId]
            FROM inserted new
                INNER JOIN [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
                    ON new.[OrganizationDepartmentId] = tuples.[SourceEducationOrganizationId]
        ) AS targets
        WHERE sources.[OrganizationDepartmentId] = targets.[OrganizationDepartmentId]
    ) AS source
        ON target.[SourceEducationOrganizationId] = source.[SourceEducationOrganizationId]
        AND target.[TargetEducationOrganizationId] = source.[TargetEducationOrganizationId]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
        VALUES (source.[SourceEducationOrganizationId], source.[TargetEducationOrganizationId]);
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_ReferentialIdentity]
ON [edfi].[OrganizationDepartment]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 189;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiOrganizationDepartment' AS nvarchar(max)) + N'$.organizationDepartmentId=' + CAST(i.[OrganizationDepartmentId] AS nvarchar(max))), i.[DocumentId], 189
        FROM inserted i;
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[OrganizationDepartmentId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i;
    END
    ELSE IF (UPDATE([OrganizationDepartmentId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[OrganizationDepartmentId] <> d.[OrganizationDepartmentId] OR (i.[OrganizationDepartmentId] IS NULL AND d.[OrganizationDepartmentId] IS NOT NULL) OR (i.[OrganizationDepartmentId] IS NOT NULL AND d.[OrganizationDepartmentId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 189;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiOrganizationDepartment' AS nvarchar(max)) + N'$.organizationDepartmentId=' + CAST(i.[OrganizationDepartmentId] AS nvarchar(max))), i.[DocumentId], 189
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[OrganizationDepartmentId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_OrganizationDepartment_Stamp]
ON [edfi].[OrganizationDepartment]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[ParentEducationOrganization_DocumentId] <> del.[ParentEducationOrganization_DocumentId] OR (i.[ParentEducationOrganization_DocumentId] IS NULL AND del.[ParentEducationOrganization_DocumentId] IS NOT NULL) OR (i.[ParentEducationOrganization_DocumentId] IS NOT NULL AND del.[ParentEducationOrganization_DocumentId] IS NULL)) OR (i.[ParentEducationOrganization_EducationOrganizationId] <> del.[ParentEducationOrganization_EducationOrganizationId] OR (i.[ParentEducationOrganization_EducationOrganizationId] IS NULL AND del.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[ParentEducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[ParentEducationOrganization_EducationOrganizationId] IS NULL)) OR (i.[AcademicSubjectDescriptor_DescriptorId] <> del.[AcademicSubjectDescriptor_DescriptorId] OR (i.[AcademicSubjectDescriptor_DescriptorId] IS NULL AND del.[AcademicSubjectDescriptor_DescriptorId] IS NOT NULL) OR (i.[AcademicSubjectDescriptor_DescriptorId] IS NOT NULL AND del.[AcademicSubjectDescriptor_DescriptorId] IS NULL)) OR (i.[OperationalStatusDescriptor_DescriptorId] <> del.[OperationalStatusDescriptor_DescriptorId] OR (i.[OperationalStatusDescriptor_DescriptorId] IS NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[NameOfInstitution] AS varbinary(max)) <> CAST(del.[NameOfInstitution] AS varbinary(max)) OR (i.[NameOfInstitution] IS NULL AND del.[NameOfInstitution] IS NOT NULL) OR (i.[NameOfInstitution] IS NOT NULL AND del.[NameOfInstitution] IS NULL)) OR (i.[OrganizationDepartmentId] <> del.[OrganizationDepartmentId] OR (i.[OrganizationDepartmentId] IS NULL AND del.[OrganizationDepartmentId] IS NOT NULL) OR (i.[OrganizationDepartmentId] IS NOT NULL AND del.[OrganizationDepartmentId] IS NULL)) OR (CAST(i.[ShortNameOfInstitution] AS varbinary(max)) <> CAST(del.[ShortNameOfInstitution] AS varbinary(max)) OR (i.[ShortNameOfInstitution] IS NULL AND del.[ShortNameOfInstitution] IS NOT NULL) OR (i.[ShortNameOfInstitution] IS NOT NULL AND del.[ShortNameOfInstitution] IS NULL)) OR (CAST(i.[WebSite] AS varbinary(max)) <> CAST(del.[WebSite] AS varbinary(max)) OR (i.[WebSite] IS NULL AND del.[WebSite] IS NOT NULL) OR (i.[WebSite] IS NOT NULL AND del.[WebSite] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[OrganizationDepartment] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[OrganizationDepartment] (
            [OldOrganizationDepartmentId],
            [OldParentEducationOrganization_EducationOrganizationId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[OrganizationDepartmentId],
            del.[ParentEducationOrganization_EducationOrganizationId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND (UPDATE([OrganizationDepartmentId]))
    BEGIN
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[OrganizationDepartmentId] <> del.[OrganizationDepartmentId] OR (i.[OrganizationDepartmentId] IS NULL AND del.[OrganizationDepartmentId] IS NOT NULL) OR (i.[OrganizationDepartmentId] IS NOT NULL AND del.[OrganizationDepartmentId] IS NULL));
    END
END;
GO

