CREATE OR ALTER TRIGGER [edfi].[TR_PostSecondaryInstitution_AbstractIdentity]
ON [edfi].[PostSecondaryInstitution]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        UPDATE t
        SET t.[EducationOrganizationId] = s.[PostSecondaryInstitutionId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN inserted s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[PostSecondaryInstitutionId], N'Ed-Fi:PostSecondaryInstitution'
        FROM inserted s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
    ELSE IF (UPDATE([PostSecondaryInstitutionId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[PostSecondaryInstitutionId] <> d.[PostSecondaryInstitutionId] OR (i.[PostSecondaryInstitutionId] IS NULL AND d.[PostSecondaryInstitutionId] IS NOT NULL) OR (i.[PostSecondaryInstitutionId] IS NOT NULL AND d.[PostSecondaryInstitutionId] IS NULL));
        UPDATE t
        SET t.[EducationOrganizationId] = s.[PostSecondaryInstitutionId]
        FROM [edfi].[EducationOrganizationIdentity] t
        INNER JOIN (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s ON t.[DocumentId] = s.[DocumentId];
        INSERT INTO [edfi].[EducationOrganizationIdentity] ([DocumentId], [EducationOrganizationId], [Discriminator])
        SELECT s.[DocumentId], s.[PostSecondaryInstitutionId], N'Ed-Fi:PostSecondaryInstitution'
        FROM (SELECT i.* FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId]) AS s
        LEFT JOIN [edfi].[EducationOrganizationIdentity] existing ON existing.[DocumentId] = s.[DocumentId]
        WHERE existing.[DocumentId] IS NULL;
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_PostSecondaryInstitution_AuthHierarchy_Delete]
ON [edfi].[PostSecondaryInstitution]
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DELETE tuples
    FROM [auth].[EducationOrganizationIdToEducationOrganizationId] AS tuples
        INNER JOIN deleted old
            ON tuples.[SourceEducationOrganizationId] = old.[PostSecondaryInstitutionId]
            AND tuples.[TargetEducationOrganizationId] = old.[PostSecondaryInstitutionId];
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_PostSecondaryInstitution_AuthHierarchy_Insert]
ON [edfi].[PostSecondaryInstitution]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [auth].[EducationOrganizationIdToEducationOrganizationId] ([SourceEducationOrganizationId], [TargetEducationOrganizationId])
    SELECT new.[PostSecondaryInstitutionId], new.[PostSecondaryInstitutionId]
    FROM inserted new;
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_PostSecondaryInstitution_ReferentialIdentity]
ON [edfi].[PostSecondaryInstitution]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 201;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiPostSecondaryInstitution' AS nvarchar(max)) + N'$.postSecondaryInstitutionId=' + CAST(i.[PostSecondaryInstitutionId] AS nvarchar(max))), i.[DocumentId], 201
        FROM inserted i;
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[PostSecondaryInstitutionId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i;
    END
    ELSE IF (UPDATE([PostSecondaryInstitutionId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[PostSecondaryInstitutionId] <> d.[PostSecondaryInstitutionId] OR (i.[PostSecondaryInstitutionId] IS NULL AND d.[PostSecondaryInstitutionId] IS NOT NULL) OR (i.[PostSecondaryInstitutionId] IS NOT NULL AND d.[PostSecondaryInstitutionId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 201;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiPostSecondaryInstitution' AS nvarchar(max)) + N'$.postSecondaryInstitutionId=' + CAST(i.[PostSecondaryInstitutionId] AS nvarchar(max))), i.[DocumentId], 201
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 95;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiEducationOrganization' AS nvarchar(max)) + N'$.educationOrganizationId=' + CAST(i.[PostSecondaryInstitutionId] AS nvarchar(max))), i.[DocumentId], 95
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_PostSecondaryInstitution_Stamp]
ON [edfi].[PostSecondaryInstitution]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[AdministrativeFundingControlDescriptor_DescriptorId] <> del.[AdministrativeFundingControlDescriptor_DescriptorId] OR (i.[AdministrativeFundingControlDescriptor_DescriptorId] IS NULL AND del.[AdministrativeFundingControlDescriptor_DescriptorId] IS NOT NULL) OR (i.[AdministrativeFundingControlDescriptor_DescriptorId] IS NOT NULL AND del.[AdministrativeFundingControlDescriptor_DescriptorId] IS NULL)) OR (i.[OperationalStatusDescriptor_DescriptorId] <> del.[OperationalStatusDescriptor_DescriptorId] OR (i.[OperationalStatusDescriptor_DescriptorId] IS NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[OperationalStatusDescriptor_DescriptorId] IS NOT NULL AND del.[OperationalStatusDescriptor_DescriptorId] IS NULL)) OR (i.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] <> del.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] OR (i.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] IS NULL AND del.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] IS NOT NULL) OR (i.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] IS NOT NULL AND del.[PostSecondaryInstitutionLevelDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[NameOfInstitution] AS varbinary(max)) <> CAST(del.[NameOfInstitution] AS varbinary(max)) OR (i.[NameOfInstitution] IS NULL AND del.[NameOfInstitution] IS NOT NULL) OR (i.[NameOfInstitution] IS NOT NULL AND del.[NameOfInstitution] IS NULL)) OR (i.[PostSecondaryInstitutionId] <> del.[PostSecondaryInstitutionId] OR (i.[PostSecondaryInstitutionId] IS NULL AND del.[PostSecondaryInstitutionId] IS NOT NULL) OR (i.[PostSecondaryInstitutionId] IS NOT NULL AND del.[PostSecondaryInstitutionId] IS NULL)) OR (CAST(i.[ShortNameOfInstitution] AS varbinary(max)) <> CAST(del.[ShortNameOfInstitution] AS varbinary(max)) OR (i.[ShortNameOfInstitution] IS NULL AND del.[ShortNameOfInstitution] IS NOT NULL) OR (i.[ShortNameOfInstitution] IS NOT NULL AND del.[ShortNameOfInstitution] IS NULL)) OR (CAST(i.[WebSite] AS varbinary(max)) <> CAST(del.[WebSite] AS varbinary(max)) OR (i.[WebSite] IS NULL AND del.[WebSite] IS NOT NULL) OR (i.[WebSite] IS NOT NULL AND del.[WebSite] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[PostSecondaryInstitution] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[PostSecondaryInstitution] (
            [OldPostSecondaryInstitutionId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[PostSecondaryInstitutionId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND (UPDATE([PostSecondaryInstitutionId]))
    BEGIN
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[PostSecondaryInstitutionId] <> del.[PostSecondaryInstitutionId] OR (i.[PostSecondaryInstitutionId] IS NULL AND del.[PostSecondaryInstitutionId] IS NOT NULL) OR (i.[PostSecondaryInstitutionId] IS NOT NULL AND del.[PostSecondaryInstitutionId] IS NULL));
    END
END;
GO

