ON [edfi].[ProgramDimensionReportingTag]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    ;WITH affectedDocs AS (
        SELECT i.[ProgramDimension_DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[CollectionItemId] = i.[CollectionItemId]
        WHERE del.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[ProgramDimension_DocumentId] <> del.[ProgramDimension_DocumentId] OR (i.[ProgramDimension_DocumentId] IS NULL AND del.[ProgramDimension_DocumentId] IS NOT NULL) OR (i.[ProgramDimension_DocumentId] IS NOT NULL AND del.[ProgramDimension_DocumentId] IS NULL)) OR (i.[ReportingTagDescriptor_DescriptorId] <> del.[ReportingTagDescriptor_DescriptorId] OR (i.[ReportingTagDescriptor_DescriptorId] IS NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NOT NULL) OR (i.[ReportingTagDescriptor_DescriptorId] IS NOT NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NULL))
        UNION
        SELECT del.[ProgramDimension_DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[CollectionItemId] = del.[CollectionItemId]
        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[ProgramDimension_DocumentId] <> del.[ProgramDimension_DocumentId] OR (i.[ProgramDimension_DocumentId] IS NULL AND del.[ProgramDimension_DocumentId] IS NOT NULL) OR (i.[ProgramDimension_DocumentId] IS NOT NULL AND del.[ProgramDimension_DocumentId] IS NULL)) OR (i.[ReportingTagDescriptor_DescriptorId] <> del.[ReportingTagDescriptor_DescriptorId] OR (i.[ReportingTagDescriptor_DescriptorId] IS NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NOT NULL) OR (i.[ReportingTagDescriptor_DescriptorId] IS NOT NULL AND del.[ReportingTagDescriptor_DescriptorId] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[ProgramDimension_DocumentId]
    INNER JOIN [edfi].[ProgramDimension] stampTarget ON stampTarget.[DocumentId] = a.[ProgramDimension_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[ProgramDimension] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
