CREATE OR ALTER TRIGGER [edfi].[TR_ProgramEvaluation_Stamp]
ON [edfi].[ProgramEvaluation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[ProgramProgram_DocumentId] <> del.[ProgramProgram_DocumentId] OR (i.[ProgramProgram_DocumentId] IS NULL AND del.[ProgramProgram_DocumentId] IS NOT NULL) OR (i.[ProgramProgram_DocumentId] IS NOT NULL AND del.[ProgramProgram_DocumentId] IS NULL)) OR (i.[ProgramProgram_EducationOrganizationId] <> del.[ProgramProgram_EducationOrganizationId] OR (i.[ProgramProgram_EducationOrganizationId] IS NULL AND del.[ProgramProgram_EducationOrganizationId] IS NOT NULL) OR (i.[ProgramProgram_EducationOrganizationId] IS NOT NULL AND del.[ProgramProgram_EducationOrganizationId] IS NULL)) OR (CAST(i.[ProgramProgram_ProgramName] AS varbinary(max)) <> CAST(del.[ProgramProgram_ProgramName] AS varbinary(max)) OR (i.[ProgramProgram_ProgramName] IS NULL AND del.[ProgramProgram_ProgramName] IS NOT NULL) OR (i.[ProgramProgram_ProgramName] IS NOT NULL AND del.[ProgramProgram_ProgramName] IS NULL)) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] <> del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL)) OR (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] <> del.[ProgramEvaluationPeriodDescriptor_DescriptorId] OR (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NULL AND del.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NULL)) OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] <> del.[ProgramEvaluationTypeDescriptor_DescriptorId] OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NULL AND del.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NULL)) OR (i.[EvaluationMaxNumericRating] <> del.[EvaluationMaxNumericRating] OR (i.[EvaluationMaxNumericRating] IS NULL AND del.[EvaluationMaxNumericRating] IS NOT NULL) OR (i.[EvaluationMaxNumericRating] IS NOT NULL AND del.[EvaluationMaxNumericRating] IS NULL)) OR (i.[EvaluationMinNumericRating] <> del.[EvaluationMinNumericRating] OR (i.[EvaluationMinNumericRating] IS NULL AND del.[EvaluationMinNumericRating] IS NOT NULL) OR (i.[EvaluationMinNumericRating] IS NOT NULL AND del.[EvaluationMinNumericRating] IS NULL)) OR (CAST(i.[ProgramEvaluationDescription] AS varbinary(max)) <> CAST(del.[ProgramEvaluationDescription] AS varbinary(max)) OR (i.[ProgramEvaluationDescription] IS NULL AND del.[ProgramEvaluationDescription] IS NOT NULL) OR (i.[ProgramEvaluationDescription] IS NOT NULL AND del.[ProgramEvaluationDescription] IS NULL)) OR (CAST(i.[ProgramEvaluationTitle] AS varbinary(max)) <> CAST(del.[ProgramEvaluationTitle] AS varbinary(max)) OR (i.[ProgramEvaluationTitle] IS NULL AND del.[ProgramEvaluationTitle] IS NOT NULL) OR (i.[ProgramEvaluationTitle] IS NOT NULL AND del.[ProgramEvaluationTitle] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[ProgramEvaluation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[ProgramEvaluation] (
            [OldProgramEvaluationPeriodDescriptor_Namespace],
            [OldProgramEvaluationPeriodDescriptor_CodeValue],
            [OldProgramEvaluationTitle],
            [OldProgramEvaluationTypeDescriptor_Namespace],
            [OldProgramEvaluationTypeDescriptor_CodeValue],
            [OldProgramProgram_EducationOrganizationId],
            [OldProgramProgram_ProgramName],
            [OldProgramProgram_ProgramTypeDescriptor_Namespace],
            [OldProgramProgram_ProgramTypeDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[ProgramEvaluationTitle],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            del.[ProgramProgram_EducationOrganizationId],
            del.[ProgramProgram_ProgramName],
            oldDj2.[Namespace],
            oldDj2.[CodeValue],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj1 ON oldDj1.[DocumentId] = del.[ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj2 ON oldDj2.[DocumentId] = del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] <> del.[ProgramEvaluationPeriodDescriptor_DescriptorId] OR (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NULL AND del.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationPeriodDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[ProgramEvaluationTitle] AS varbinary(max)) <> CAST(del.[ProgramEvaluationTitle] AS varbinary(max)) OR (i.[ProgramEvaluationTitle] IS NULL AND del.[ProgramEvaluationTitle] IS NOT NULL) OR (i.[ProgramEvaluationTitle] IS NOT NULL AND del.[ProgramEvaluationTitle] IS NULL)) OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] <> del.[ProgramEvaluationTypeDescriptor_DescriptorId] OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NULL AND del.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationTypeDescriptor_DescriptorId] IS NULL)) OR (i.[ProgramProgram_EducationOrganizationId] <> del.[ProgramProgram_EducationOrganizationId] OR (i.[ProgramProgram_EducationOrganizationId] IS NULL AND del.[ProgramProgram_EducationOrganizationId] IS NOT NULL) OR (i.[ProgramProgram_EducationOrganizationId] IS NOT NULL AND del.[ProgramProgram_EducationOrganizationId] IS NULL)) OR (CAST(i.[ProgramProgram_ProgramName] AS varbinary(max)) <> CAST(del.[ProgramProgram_ProgramName] AS varbinary(max)) OR (i.[ProgramProgram_ProgramName] IS NULL AND del.[ProgramProgram_ProgramName] IS NOT NULL) OR (i.[ProgramProgram_ProgramName] IS NOT NULL AND del.[ProgramProgram_ProgramName] IS NULL)) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] <> del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NOT NULL AND del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[ProgramEvaluation] (
            [OldProgramEvaluationPeriodDescriptor_Namespace],
            [OldProgramEvaluationPeriodDescriptor_CodeValue],
            [OldProgramEvaluationTitle],
            [OldProgramEvaluationTypeDescriptor_Namespace],
            [OldProgramEvaluationTypeDescriptor_CodeValue],
            [OldProgramProgram_EducationOrganizationId],
            [OldProgramProgram_ProgramName],
            [OldProgramProgram_ProgramTypeDescriptor_Namespace],
            [OldProgramProgram_ProgramTypeDescriptor_CodeValue],
            [NewProgramEvaluationPeriodDescriptor_Namespace],
            [NewProgramEvaluationPeriodDescriptor_CodeValue],
            [NewProgramEvaluationTitle],
            [NewProgramEvaluationTypeDescriptor_Namespace],
            [NewProgramEvaluationTypeDescriptor_CodeValue],
            [NewProgramProgram_EducationOrganizationId],
            [NewProgramProgram_ProgramName],
            [NewProgramProgram_ProgramTypeDescriptor_Namespace],
            [NewProgramProgram_ProgramTypeDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[ProgramEvaluationTitle],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            del.[ProgramProgram_EducationOrganizationId],
            del.[ProgramProgram_ProgramName],
            oldDj2.[Namespace],
            oldDj2.[CodeValue],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[ProgramEvaluationTitle],
            newDj1.[Namespace],
            newDj1.[CodeValue],
            i.[ProgramProgram_EducationOrganizationId],
            i.[ProgramProgram_ProgramName],
            newDj2.[Namespace],
            newDj2.[CodeValue],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj1 ON oldDj1.[DocumentId] = del.[ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj2 ON oldDj2.[DocumentId] = del.[ProgramProgram_ProgramTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj0 ON newDj0.[DocumentId] = i.[ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj1 ON newDj1.[DocumentId] = i.[ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj2 ON newDj2.[DocumentId] = i.[ProgramProgram_ProgramTypeDescriptor_DescriptorId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_ProgramEvaluationElement_ReferentialIdentity]
ON [edfi].[ProgramEvaluationElement]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 213;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiProgramEvaluationElement' AS nvarchar(max)) + N'$.programEvaluationElementTitle=' + i.[ProgramEvaluationElementTitle] + N'#' + N'$.programEvaluationReference.programEducationOrganizationId=' + CAST(i.[ProgramEvaluation_ProgramEducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.programEvaluationReference.programEvaluationPeriodDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationPeriodDescriptor_DescriptorId])) + N'#' + N'$.programEvaluationReference.programEvaluationTitle=' + i.[ProgramEvaluation_ProgramEvaluationTitle] + N'#' + N'$.programEvaluationReference.programEvaluationTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationTypeDescriptor_DescriptorId])) + N'#' + N'$.programEvaluationReference.programName=' + i.[ProgramEvaluation_ProgramName] + N'#' + N'$.programEvaluationReference.programTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramTypeDescriptor_DescriptorId]))), i.[DocumentId], 213
        FROM inserted i;
    END
    ELSE IF (UPDATE([ProgramEvaluationElementTitle]) OR UPDATE([ProgramEducationOrganizationId_Unified]) OR UPDATE([ProgramEvaluationPeriodDescriptor_Unified_DescriptorId]) OR UPDATE([ProgramEvaluationTitle_Unified]) OR UPDATE([ProgramEvaluationTypeDescriptor_Unified_DescriptorId]) OR UPDATE([ProgramName_Unified]) OR UPDATE([ProgramTypeDescriptor_Unified_DescriptorId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[ProgramEvaluationElementTitle] AS varbinary(max)) <> CAST(d.[ProgramEvaluationElementTitle] AS varbinary(max)) OR (i.[ProgramEvaluationElementTitle] IS NULL AND d.[ProgramEvaluationElementTitle] IS NOT NULL) OR (i.[ProgramEvaluationElementTitle] IS NOT NULL AND d.[ProgramEvaluationElementTitle] IS NULL)) OR (i.[ProgramEducationOrganizationId_Unified] <> d.[ProgramEducationOrganizationId_Unified] OR (i.[ProgramEducationOrganizationId_Unified] IS NULL AND d.[ProgramEducationOrganizationId_Unified] IS NOT NULL) OR (i.[ProgramEducationOrganizationId_Unified] IS NOT NULL AND d.[ProgramEducationOrganizationId_Unified] IS NULL)) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] <> d.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL AND d.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL AND d.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramEvaluationTitle_Unified] AS varbinary(max)) <> CAST(d.[ProgramEvaluationTitle_Unified] AS varbinary(max)) OR (i.[ProgramEvaluationTitle_Unified] IS NULL AND d.[ProgramEvaluationTitle_Unified] IS NOT NULL) OR (i.[ProgramEvaluationTitle_Unified] IS NOT NULL AND d.[ProgramEvaluationTitle_Unified] IS NULL)) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] <> d.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL AND d.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND d.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramName_Unified] AS varbinary(max)) <> CAST(d.[ProgramName_Unified] AS varbinary(max)) OR (i.[ProgramName_Unified] IS NULL AND d.[ProgramName_Unified] IS NOT NULL) OR (i.[ProgramName_Unified] IS NOT NULL AND d.[ProgramName_Unified] IS NULL)) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] <> d.[ProgramTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL AND d.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND d.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 213;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiProgramEvaluationElement' AS nvarchar(max)) + N'$.programEvaluationElementTitle=' + i.[ProgramEvaluationElementTitle] + N'#' + N'$.programEvaluationReference.programEducationOrganizationId=' + CAST(i.[ProgramEvaluation_ProgramEducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.programEvaluationReference.programEvaluationPeriodDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationPeriodDescriptor_DescriptorId])) + N'#' + N'$.programEvaluationReference.programEvaluationTitle=' + i.[ProgramEvaluation_ProgramEvaluationTitle] + N'#' + N'$.programEvaluationReference.programEvaluationTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationTypeDescriptor_DescriptorId])) + N'#' + N'$.programEvaluationReference.programName=' + i.[ProgramEvaluation_ProgramName] + N'#' + N'$.programEvaluationReference.programTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[ProgramEvaluation_ProgramTypeDescriptor_DescriptorId]))), i.[DocumentId], 213
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
