    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[ProgramEducationOrganizationId_Unified] <> del.[ProgramEducationOrganizationId_Unified] OR (i.[ProgramEducationOrganizationId_Unified] IS NULL AND del.[ProgramEducationOrganizationId_Unified] IS NOT NULL) OR (i.[ProgramEducationOrganizationId_Unified] IS NOT NULL AND del.[ProgramEducationOrganizationId_Unified] IS NULL)) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] <> del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramEvaluationTitle_Unified] AS varbinary(max)) <> CAST(del.[ProgramEvaluationTitle_Unified] AS varbinary(max)) OR (i.[ProgramEvaluationTitle_Unified] IS NULL AND del.[ProgramEvaluationTitle_Unified] IS NOT NULL) OR (i.[ProgramEvaluationTitle_Unified] IS NOT NULL AND del.[ProgramEvaluationTitle_Unified] IS NULL)) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] <> del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramName_Unified] AS varbinary(max)) <> CAST(del.[ProgramName_Unified] AS varbinary(max)) OR (i.[ProgramName_Unified] IS NULL AND del.[ProgramName_Unified] IS NOT NULL) OR (i.[ProgramName_Unified] IS NOT NULL AND del.[ProgramName_Unified] IS NULL)) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] <> del.[ProgramTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL)) OR (i.[ProgramEvaluationObjective_DocumentId] <> del.[ProgramEvaluationObjective_DocumentId] OR (i.[ProgramEvaluationObjective_DocumentId] IS NULL AND del.[ProgramEvaluationObjective_DocumentId] IS NOT NULL) OR (i.[ProgramEvaluationObjective_DocumentId] IS NOT NULL AND del.[ProgramEvaluationObjective_DocumentId] IS NULL)) OR (CAST(i.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] AS varbinary(max)) <> CAST(del.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] AS varbinary(max)) OR (i.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] IS NULL AND del.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] IS NOT NULL) OR (i.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] IS NOT NULL AND del.[ProgramEvaluationObjective_ProgramEvaluationObjectiveTitle] IS NULL)) OR (i.[ProgramEvaluation_DocumentId] <> del.[ProgramEvaluation_DocumentId] OR (i.[ProgramEvaluation_DocumentId] IS NULL AND del.[ProgramEvaluation_DocumentId] IS NOT NULL) OR (i.[ProgramEvaluation_DocumentId] IS NOT NULL AND del.[ProgramEvaluation_DocumentId] IS NULL)) OR (i.[ElementMaxNumericRating] <> del.[ElementMaxNumericRating] OR (i.[ElementMaxNumericRating] IS NULL AND del.[ElementMaxNumericRating] IS NOT NULL) OR (i.[ElementMaxNumericRating] IS NOT NULL AND del.[ElementMaxNumericRating] IS NULL)) OR (i.[ElementMinNumericRating] <> del.[ElementMinNumericRating] OR (i.[ElementMinNumericRating] IS NULL AND del.[ElementMinNumericRating] IS NOT NULL) OR (i.[ElementMinNumericRating] IS NOT NULL AND del.[ElementMinNumericRating] IS NULL)) OR (i.[ElementSortOrder] <> del.[ElementSortOrder] OR (i.[ElementSortOrder] IS NULL AND del.[ElementSortOrder] IS NOT NULL) OR (i.[ElementSortOrder] IS NOT NULL AND del.[ElementSortOrder] IS NULL)) OR (CAST(i.[ProgramEvaluationElementDescription] AS varbinary(max)) <> CAST(del.[ProgramEvaluationElementDescription] AS varbinary(max)) OR (i.[ProgramEvaluationElementDescription] IS NULL AND del.[ProgramEvaluationElementDescription] IS NOT NULL) OR (i.[ProgramEvaluationElementDescription] IS NOT NULL AND del.[ProgramEvaluationElementDescription] IS NULL)) OR (CAST(i.[ProgramEvaluationElementTitle] AS varbinary(max)) <> CAST(del.[ProgramEvaluationElementTitle] AS varbinary(max)) OR (i.[ProgramEvaluationElementTitle] IS NULL AND del.[ProgramEvaluationElementTitle] IS NOT NULL) OR (i.[ProgramEvaluationElementTitle] IS NOT NULL AND del.[ProgramEvaluationElementTitle] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[ProgramEvaluationElement] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[ProgramEvaluationElement] (
            [OldProgramEvaluationElementTitle],
            [OldProgramEducationOrganizationId_Unified],
            [OldProgramEvaluation_ProgramEvaluationPeriodDescriptor_Namespace],
            [OldProgramEvaluation_ProgramEvaluationPeriodDescriptor_CodeValue],
            [OldProgramEvaluationTitle_Unified],
            [OldProgramEvaluation_ProgramEvaluationTypeDescriptor_Namespace],
            [OldProgramEvaluation_ProgramEvaluationTypeDescriptor_CodeValue],
            [OldProgramName_Unified],
            [OldProgramEvaluation_ProgramTypeDescriptor_Namespace],
            [OldProgramEvaluation_ProgramTypeDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[ProgramEvaluationElementTitle],
            del.[ProgramEducationOrganizationId_Unified],
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[ProgramEvaluationTitle_Unified],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            del.[ProgramName_Unified],
            oldDj2.[Namespace],
            oldDj2.[CodeValue],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ProgramEvaluation_ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj1 ON oldDj1.[DocumentId] = del.[ProgramEvaluation_ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj2 ON oldDj2.[DocumentId] = del.[ProgramEvaluation_ProgramTypeDescriptor_DescriptorId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[ProgramEvaluationElementTitle] AS varbinary(max)) <> CAST(del.[ProgramEvaluationElementTitle] AS varbinary(max)) OR (i.[ProgramEvaluationElementTitle] IS NULL AND del.[ProgramEvaluationElementTitle] IS NOT NULL) OR (i.[ProgramEvaluationElementTitle] IS NOT NULL AND del.[ProgramEvaluationElementTitle] IS NULL)) OR (i.[ProgramEducationOrganizationId_Unified] <> del.[ProgramEducationOrganizationId_Unified] OR (i.[ProgramEducationOrganizationId_Unified] IS NULL AND del.[ProgramEducationOrganizationId_Unified] IS NOT NULL) OR (i.[ProgramEducationOrganizationId_Unified] IS NOT NULL AND del.[ProgramEducationOrganizationId_Unified] IS NULL)) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] <> del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationPeriodDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramEvaluationTitle_Unified] AS varbinary(max)) <> CAST(del.[ProgramEvaluationTitle_Unified] AS varbinary(max)) OR (i.[ProgramEvaluationTitle_Unified] IS NULL AND del.[ProgramEvaluationTitle_Unified] IS NOT NULL) OR (i.[ProgramEvaluationTitle_Unified] IS NOT NULL AND del.[ProgramEvaluationTitle_Unified] IS NULL)) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] <> del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramEvaluationTypeDescriptor_Unified_DescriptorId] IS NULL)) OR (CAST(i.[ProgramName_Unified] AS varbinary(max)) <> CAST(del.[ProgramName_Unified] AS varbinary(max)) OR (i.[ProgramName_Unified] IS NULL AND del.[ProgramName_Unified] IS NOT NULL) OR (i.[ProgramName_Unified] IS NOT NULL AND del.[ProgramName_Unified] IS NULL)) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] <> del.[ProgramTypeDescriptor_Unified_DescriptorId] OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL AND del.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL) OR (i.[ProgramTypeDescriptor_Unified_DescriptorId] IS NOT NULL AND del.[ProgramTypeDescriptor_Unified_DescriptorId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[ProgramEvaluationElement] (
            [OldProgramEvaluationElementTitle],
            [OldProgramEducationOrganizationId_Unified],
            [OldProgramEvaluation_ProgramEvaluationPeriodDescriptor_Namespace],
            [OldProgramEvaluation_ProgramEvaluationPeriodDescriptor_CodeValue],
            [OldProgramEvaluationTitle_Unified],
            [OldProgramEvaluation_ProgramEvaluationTypeDescriptor_Namespace],
            [OldProgramEvaluation_ProgramEvaluationTypeDescriptor_CodeValue],
            [OldProgramName_Unified],
            [OldProgramEvaluation_ProgramTypeDescriptor_Namespace],
            [OldProgramEvaluation_ProgramTypeDescriptor_CodeValue],
            [NewProgramEvaluationElementTitle],
            [NewProgramEducationOrganizationId_Unified],
            [NewProgramEvaluation_ProgramEvaluationPeriodDescriptor_Namespace],
            [NewProgramEvaluation_ProgramEvaluationPeriodDescriptor_CodeValue],
            [NewProgramEvaluationTitle_Unified],
            [NewProgramEvaluation_ProgramEvaluationTypeDescriptor_Namespace],
            [NewProgramEvaluation_ProgramEvaluationTypeDescriptor_CodeValue],
            [NewProgramName_Unified],
            [NewProgramEvaluation_ProgramTypeDescriptor_Namespace],
            [NewProgramEvaluation_ProgramTypeDescriptor_CodeValue],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[ProgramEvaluationElementTitle],
            del.[ProgramEducationOrganizationId_Unified],
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[ProgramEvaluationTitle_Unified],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            del.[ProgramName_Unified],
            oldDj2.[Namespace],
            oldDj2.[CodeValue],
            i.[ProgramEvaluationElementTitle],
            i.[ProgramEducationOrganizationId_Unified],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[ProgramEvaluationTitle_Unified],
            newDj1.[Namespace],
            newDj1.[CodeValue],
            i.[ProgramName_Unified],
            newDj2.[Namespace],
            newDj2.[CodeValue],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[ProgramEvaluation_ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj1 ON oldDj1.[DocumentId] = del.[ProgramEvaluation_ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] oldDj2 ON oldDj2.[DocumentId] = del.[ProgramEvaluation_ProgramTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj0 ON newDj0.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationPeriodDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj1 ON newDj1.[DocumentId] = i.[ProgramEvaluation_ProgramEvaluationTypeDescriptor_DescriptorId]
        INNER JOIN [dms].[Descriptor] newDj2 ON newDj2.[DocumentId] = i.[ProgramEvaluation_ProgramTypeDescriptor_DescriptorId];
    END
END;
