        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[SchoolId_Unified] <> del.[SchoolId_Unified] OR (i.[SchoolId_Unified] IS NULL AND del.[SchoolId_Unified] IS NOT NULL) OR (i.[SchoolId_Unified] IS NOT NULL AND del.[SchoolId_Unified] IS NULL)) OR (i.[SchoolYear_Unified] <> del.[SchoolYear_Unified] OR (i.[SchoolYear_Unified] IS NULL AND del.[SchoolYear_Unified] IS NOT NULL) OR (i.[SchoolYear_Unified] IS NOT NULL AND del.[SchoolYear_Unified] IS NULL)) OR (i.[CalendarDate_DocumentId] <> del.[CalendarDate_DocumentId] OR (i.[CalendarDate_DocumentId] IS NULL AND del.[CalendarDate_DocumentId] IS NOT NULL) OR (i.[CalendarDate_DocumentId] IS NOT NULL AND del.[CalendarDate_DocumentId] IS NULL)) OR (CAST(i.[CalendarDate_CalendarCode] AS varbinary(max)) <> CAST(del.[CalendarDate_CalendarCode] AS varbinary(max)) OR (i.[CalendarDate_CalendarCode] IS NULL AND del.[CalendarDate_CalendarCode] IS NOT NULL) OR (i.[CalendarDate_CalendarCode] IS NOT NULL AND del.[CalendarDate_CalendarCode] IS NULL)) OR (i.[CalendarDate_Date] <> del.[CalendarDate_Date] OR (i.[CalendarDate_Date] IS NULL AND del.[CalendarDate_Date] IS NOT NULL) OR (i.[CalendarDate_Date] IS NOT NULL AND del.[CalendarDate_Date] IS NULL)) OR (i.[Section_DocumentId] <> del.[Section_DocumentId] OR (i.[Section_DocumentId] IS NULL AND del.[Section_DocumentId] IS NOT NULL) OR (i.[Section_DocumentId] IS NOT NULL AND del.[Section_DocumentId] IS NULL)) OR (CAST(i.[Section_LocalCourseCode] AS varbinary(max)) <> CAST(del.[Section_LocalCourseCode] AS varbinary(max)) OR (i.[Section_LocalCourseCode] IS NULL AND del.[Section_LocalCourseCode] IS NOT NULL) OR (i.[Section_LocalCourseCode] IS NOT NULL AND del.[Section_LocalCourseCode] IS NULL)) OR (CAST(i.[Section_SessionName] AS varbinary(max)) <> CAST(del.[Section_SessionName] AS varbinary(max)) OR (i.[Section_SessionName] IS NULL AND del.[Section_SessionName] IS NOT NULL) OR (i.[Section_SessionName] IS NOT NULL AND del.[Section_SessionName] IS NULL)) OR (CAST(i.[Section_SectionIdentifier] AS varbinary(max)) <> CAST(del.[Section_SectionIdentifier] AS varbinary(max)) OR (i.[Section_SectionIdentifier] IS NULL AND del.[Section_SectionIdentifier] IS NOT NULL) OR (i.[Section_SectionIdentifier] IS NOT NULL AND del.[Section_SectionIdentifier] IS NULL)) OR (i.[Staff_DocumentId] <> del.[Staff_DocumentId] OR (i.[Staff_DocumentId] IS NULL AND del.[Staff_DocumentId] IS NOT NULL) OR (i.[Staff_DocumentId] IS NOT NULL AND del.[Staff_DocumentId] IS NULL)) OR (CAST(i.[Staff_StaffUniqueId] AS varbinary(max)) <> CAST(del.[Staff_StaffUniqueId] AS varbinary(max)) OR (i.[Staff_StaffUniqueId] IS NULL AND del.[Staff_StaffUniqueId] IS NOT NULL) OR (i.[Staff_StaffUniqueId] IS NOT NULL AND del.[Staff_StaffUniqueId] IS NULL)) OR (i.[EventDate] <> del.[EventDate] OR (i.[EventDate] IS NULL AND del.[EventDate] IS NOT NULL) OR (i.[EventDate] IS NOT NULL AND del.[EventDate] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[SectionAttendanceTakenEvent] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[SectionAttendanceTakenEvent] (
            [OldCalendarDate_CalendarCode],
            [OldCalendarDate_Date],
            [OldSchoolId_Unified],
            [OldSchoolYear_Unified],
            [OldSection_LocalCourseCode],
            [OldSection_SectionIdentifier],
            [OldSection_SessionName],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[CalendarDate_CalendarCode],
            del.[CalendarDate_Date],
            del.[SchoolId_Unified],
            del.[SchoolYear_Unified],
            del.[Section_LocalCourseCode],
            del.[Section_SectionIdentifier],
            del.[Section_SessionName],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[CalendarDate_CalendarCode] AS varbinary(max)) <> CAST(del.[CalendarDate_CalendarCode] AS varbinary(max)) OR (i.[CalendarDate_CalendarCode] IS NULL AND del.[CalendarDate_CalendarCode] IS NOT NULL) OR (i.[CalendarDate_CalendarCode] IS NOT NULL AND del.[CalendarDate_CalendarCode] IS NULL)) OR (i.[CalendarDate_Date] <> del.[CalendarDate_Date] OR (i.[CalendarDate_Date] IS NULL AND del.[CalendarDate_Date] IS NOT NULL) OR (i.[CalendarDate_Date] IS NOT NULL AND del.[CalendarDate_Date] IS NULL)) OR (i.[SchoolId_Unified] <> del.[SchoolId_Unified] OR (i.[SchoolId_Unified] IS NULL AND del.[SchoolId_Unified] IS NOT NULL) OR (i.[SchoolId_Unified] IS NOT NULL AND del.[SchoolId_Unified] IS NULL)) OR (i.[SchoolYear_Unified] <> del.[SchoolYear_Unified] OR (i.[SchoolYear_Unified] IS NULL AND del.[SchoolYear_Unified] IS NOT NULL) OR (i.[SchoolYear_Unified] IS NOT NULL AND del.[SchoolYear_Unified] IS NULL)) OR (CAST(i.[Section_LocalCourseCode] AS varbinary(max)) <> CAST(del.[Section_LocalCourseCode] AS varbinary(max)) OR (i.[Section_LocalCourseCode] IS NULL AND del.[Section_LocalCourseCode] IS NOT NULL) OR (i.[Section_LocalCourseCode] IS NOT NULL AND del.[Section_LocalCourseCode] IS NULL)) OR (CAST(i.[Section_SectionIdentifier] AS varbinary(max)) <> CAST(del.[Section_SectionIdentifier] AS varbinary(max)) OR (i.[Section_SectionIdentifier] IS NULL AND del.[Section_SectionIdentifier] IS NOT NULL) OR (i.[Section_SectionIdentifier] IS NOT NULL AND del.[Section_SectionIdentifier] IS NULL)) OR (CAST(i.[Section_SessionName] AS varbinary(max)) <> CAST(del.[Section_SessionName] AS varbinary(max)) OR (i.[Section_SessionName] IS NULL AND del.[Section_SessionName] IS NOT NULL) OR (i.[Section_SessionName] IS NOT NULL AND del.[Section_SessionName] IS NULL));
        INSERT INTO [tracked_changes_edfi].[SectionAttendanceTakenEvent] (
            [OldCalendarDate_CalendarCode],
            [OldCalendarDate_Date],
            [OldSchoolId_Unified],
            [OldSchoolYear_Unified],
            [OldSection_LocalCourseCode],
            [OldSection_SectionIdentifier],
            [OldSection_SessionName],
            [NewCalendarDate_CalendarCode],
            [NewCalendarDate_Date],
            [NewSchoolId_Unified],
            [NewSchoolYear_Unified],
            [NewSection_LocalCourseCode],
            [NewSection_SectionIdentifier],
            [NewSection_SessionName],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[CalendarDate_CalendarCode],
            del.[CalendarDate_Date],
            del.[SchoolId_Unified],
            del.[SchoolYear_Unified],
            del.[Section_LocalCourseCode],
            del.[Section_SectionIdentifier],
            del.[Section_SessionName],
            i.[CalendarDate_CalendarCode],
            i.[CalendarDate_Date],
            i.[SchoolId_Unified],
            i.[SchoolYear_Unified],
            i.[Section_LocalCourseCode],
            i.[Section_SectionIdentifier],
            i.[Section_SessionName],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
