            oldDj0.[CodeValue],
            del.[HireDate],
            del.[Staff_StaffUniqueId],
            oldPj0s0.[DocumentId],
            i.[EducationOrganization_EducationOrganizationId],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[HireDate],
