        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[EducationOrganization_DocumentId] <> del.[EducationOrganization_DocumentId] OR (i.[EducationOrganization_DocumentId] IS NULL AND del.[EducationOrganization_DocumentId] IS NOT NULL) OR (i.[EducationOrganization_DocumentId] IS NOT NULL AND del.[EducationOrganization_DocumentId] IS NULL)) OR (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (i.[SchoolYear_DocumentId] <> del.[SchoolYear_DocumentId] OR (i.[SchoolYear_DocumentId] IS NULL AND del.[SchoolYear_DocumentId] IS NOT NULL) OR (i.[SchoolYear_DocumentId] IS NOT NULL AND del.[SchoolYear_DocumentId] IS NULL)) OR (i.[SchoolYear_SchoolYear] <> del.[SchoolYear_SchoolYear] OR (i.[SchoolYear_SchoolYear] IS NULL AND del.[SchoolYear_SchoolYear] IS NOT NULL) OR (i.[SchoolYear_SchoolYear] IS NOT NULL AND del.[SchoolYear_SchoolYear] IS NULL)) OR (i.[StudentAssessment_DocumentId] <> del.[StudentAssessment_DocumentId] OR (i.[StudentAssessment_DocumentId] IS NULL AND del.[StudentAssessment_DocumentId] IS NOT NULL) OR (i.[StudentAssessment_DocumentId] IS NOT NULL AND del.[StudentAssessment_DocumentId] IS NULL)) OR (CAST(i.[StudentAssessment_AssessmentIdentifier] AS varbinary(max)) <> CAST(del.[StudentAssessment_AssessmentIdentifier] AS varbinary(max)) OR (i.[StudentAssessment_AssessmentIdentifier] IS NULL AND del.[StudentAssessment_AssessmentIdentifier] IS NOT NULL) OR (i.[StudentAssessment_AssessmentIdentifier] IS NOT NULL AND del.[StudentAssessment_AssessmentIdentifier] IS NULL)) OR (CAST(i.[StudentAssessment_Namespace] AS varbinary(max)) <> CAST(del.[StudentAssessment_Namespace] AS varbinary(max)) OR (i.[StudentAssessment_Namespace] IS NULL AND del.[StudentAssessment_Namespace] IS NOT NULL) OR (i.[StudentAssessment_Namespace] IS NOT NULL AND del.[StudentAssessment_Namespace] IS NULL)) OR (CAST(i.[StudentAssessment_StudentAssessmentIdentifier] AS varbinary(max)) <> CAST(del.[StudentAssessment_StudentAssessmentIdentifier] AS varbinary(max)) OR (i.[StudentAssessment_StudentAssessmentIdentifier] IS NULL AND del.[StudentAssessment_StudentAssessmentIdentifier] IS NOT NULL) OR (i.[StudentAssessment_StudentAssessmentIdentifier] IS NOT NULL AND del.[StudentAssessment_StudentAssessmentIdentifier] IS NULL)) OR (CAST(i.[StudentAssessment_StudentUniqueId] AS varbinary(max)) <> CAST(del.[StudentAssessment_StudentUniqueId] AS varbinary(max)) OR (i.[StudentAssessment_StudentUniqueId] IS NULL AND del.[StudentAssessment_StudentUniqueId] IS NOT NULL) OR (i.[StudentAssessment_StudentUniqueId] IS NOT NULL AND del.[StudentAssessment_StudentUniqueId] IS NULL)) OR (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] <> del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] OR (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NULL AND del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NOT NULL AND del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[StudentAssessmentEducationOrganizationAssociation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[StudentAssessmentEducationOrganizationAssociation] (
            [OldEducationOrganizationAssociationTypeDescriptor_Namespace],
            [OldEducationOrganizationAssociationTypeDescriptor_CodeValue],
            [OldEducationOrganization_EducationOrganizationId],
            [OldStudentAssessment_AssessmentIdentifier],
            [OldStudentAssessment_Namespace],
            [OldStudentAssessment_StudentAssessmentIdentifier],
            [OldStudentAssessment_StudentUniqueId],
            [OldStudentAssessment_Student_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[EducationOrganization_EducationOrganizationId],
            del.[StudentAssessment_AssessmentIdentifier],
            del.[StudentAssessment_Namespace],
            del.[StudentAssessment_StudentAssessmentIdentifier],
            del.[StudentAssessment_StudentUniqueId],
            oldPj0s1.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId]
        INNER JOIN [edfi].[StudentAssessment] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[StudentAssessment_DocumentId]
        INNER JOIN [edfi].[Student] oldPj0s1 ON oldPj0s1.[DocumentId] = oldPj0s0.[Student_DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] <> del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] OR (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NULL AND del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NOT NULL AND del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId] IS NULL)) OR (i.[EducationOrganization_EducationOrganizationId] <> del.[EducationOrganization_EducationOrganizationId] OR (i.[EducationOrganization_EducationOrganizationId] IS NULL AND del.[EducationOrganization_EducationOrganizationId] IS NOT NULL) OR (i.[EducationOrganization_EducationOrganizationId] IS NOT NULL AND del.[EducationOrganization_EducationOrganizationId] IS NULL)) OR (CAST(i.[StudentAssessment_AssessmentIdentifier] AS varbinary(max)) <> CAST(del.[StudentAssessment_AssessmentIdentifier] AS varbinary(max)) OR (i.[StudentAssessment_AssessmentIdentifier] IS NULL AND del.[StudentAssessment_AssessmentIdentifier] IS NOT NULL) OR (i.[StudentAssessment_AssessmentIdentifier] IS NOT NULL AND del.[StudentAssessment_AssessmentIdentifier] IS NULL)) OR (CAST(i.[StudentAssessment_Namespace] AS varbinary(max)) <> CAST(del.[StudentAssessment_Namespace] AS varbinary(max)) OR (i.[StudentAssessment_Namespace] IS NULL AND del.[StudentAssessment_Namespace] IS NOT NULL) OR (i.[StudentAssessment_Namespace] IS NOT NULL AND del.[StudentAssessment_Namespace] IS NULL)) OR (CAST(i.[StudentAssessment_StudentAssessmentIdentifier] AS varbinary(max)) <> CAST(del.[StudentAssessment_StudentAssessmentIdentifier] AS varbinary(max)) OR (i.[StudentAssessment_StudentAssessmentIdentifier] IS NULL AND del.[StudentAssessment_StudentAssessmentIdentifier] IS NOT NULL) OR (i.[StudentAssessment_StudentAssessmentIdentifier] IS NOT NULL AND del.[StudentAssessment_StudentAssessmentIdentifier] IS NULL)) OR (CAST(i.[StudentAssessment_StudentUniqueId] AS varbinary(max)) <> CAST(del.[StudentAssessment_StudentUniqueId] AS varbinary(max)) OR (i.[StudentAssessment_StudentUniqueId] IS NULL AND del.[StudentAssessment_StudentUniqueId] IS NOT NULL) OR (i.[StudentAssessment_StudentUniqueId] IS NOT NULL AND del.[StudentAssessment_StudentUniqueId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[StudentAssessmentEducationOrganizationAssociation] (
            [OldEducationOrganizationAssociationTypeDescriptor_Namespace],
            [OldEducationOrganizationAssociationTypeDescriptor_CodeValue],
            [OldEducationOrganization_EducationOrganizationId],
            [OldStudentAssessment_AssessmentIdentifier],
            [OldStudentAssessment_Namespace],
            [OldStudentAssessment_StudentAssessmentIdentifier],
            [OldStudentAssessment_StudentUniqueId],
            [OldStudentAssessment_Student_DocumentId],
            [NewEducationOrganizationAssociationTypeDescriptor_Namespace],
            [NewEducationOrganizationAssociationTypeDescriptor_CodeValue],
            [NewEducationOrganization_EducationOrganizationId],
            [NewStudentAssessment_AssessmentIdentifier],
            [NewStudentAssessment_Namespace],
            [NewStudentAssessment_StudentAssessmentIdentifier],
            [NewStudentAssessment_StudentUniqueId],
            [NewStudentAssessment_Student_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[EducationOrganization_EducationOrganizationId],
            del.[StudentAssessment_AssessmentIdentifier],
            del.[StudentAssessment_Namespace],
            del.[StudentAssessment_StudentAssessmentIdentifier],
            del.[StudentAssessment_StudentUniqueId],
            oldPj0s1.[DocumentId],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[EducationOrganization_EducationOrganizationId],
            i.[StudentAssessment_AssessmentIdentifier],
            i.[StudentAssessment_Namespace],
            i.[StudentAssessment_StudentAssessmentIdentifier],
            i.[StudentAssessment_StudentUniqueId],
            newPj0s1.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[EducationOrganizationAssociationTypeDescriptor_DescriptorId]
        INNER JOIN [edfi].[StudentAssessment] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[StudentAssessment_DocumentId]
        INNER JOIN [edfi].[Student] oldPj0s1 ON oldPj0s1.[DocumentId] = oldPj0s0.[Student_DocumentId]
        INNER JOIN [dms].[Descriptor] newDj0 ON newDj0.[DocumentId] = i.[EducationOrganizationAssociationTypeDescriptor_DescriptorId]
        INNER JOIN [edfi].[StudentAssessment] newPj0s0 ON newPj0s0.[DocumentId] = i.[StudentAssessment_DocumentId]
        INNER JOIN [edfi].[Student] newPj0s1 ON newPj0s1.[DocumentId] = newPj0s0.[Student_DocumentId];
    END
