            del.[StudentAssessmentRegistration_AssigningEducationOrganizationId],
            del.[StudentAssessmentRegistration_EducationOrganizationId],
            del.[StudentAssessmentRegistration_StudentUniqueId],
            oldPj0s2.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
