        WHERE del.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[StudentCTEProgramAssociation_DocumentId] <> del.[StudentCTEProgramAssociation_DocumentId] OR (i.[StudentCTEProgramAssociation_DocumentId] IS NULL AND del.[StudentCTEProgramAssociation_DocumentId] IS NOT NULL) OR (i.[StudentCTEProgramAssociation_DocumentId] IS NOT NULL AND del.[StudentCTEProgramAssociation_DocumentId] IS NULL)) OR (i.[ParticipationStatusDescriptor_DescriptorId] <> del.[ParticipationStatusDescriptor_DescriptorId] OR (i.[ParticipationStatusDescriptor_DescriptorId] IS NULL AND del.[ParticipationStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[ParticipationStatusDescriptor_DescriptorId] IS NOT NULL AND del.[ParticipationStatusDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[DesignatedBy] AS varbinary(max)) <> CAST(del.[DesignatedBy] AS varbinary(max)) OR (i.[DesignatedBy] IS NULL AND del.[DesignatedBy] IS NOT NULL) OR (i.[DesignatedBy] IS NOT NULL AND del.[DesignatedBy] IS NULL)) OR (i.[StatusBeginDate] <> del.[StatusBeginDate] OR (i.[StatusBeginDate] IS NULL AND del.[StatusBeginDate] IS NOT NULL) OR (i.[StatusBeginDate] IS NOT NULL AND del.[StatusBeginDate] IS NULL)) OR (i.[StatusEndDate] <> del.[StatusEndDate] OR (i.[StatusEndDate] IS NULL AND del.[StatusEndDate] IS NOT NULL) OR (i.[StatusEndDate] IS NOT NULL AND del.[StatusEndDate] IS NULL))
        UNION
        SELECT del.[StudentCTEProgramAssociation_DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[CollectionItemId] = del.[CollectionItemId]
        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[StudentCTEProgramAssociation_DocumentId] <> del.[StudentCTEProgramAssociation_DocumentId] OR (i.[StudentCTEProgramAssociation_DocumentId] IS NULL AND del.[StudentCTEProgramAssociation_DocumentId] IS NOT NULL) OR (i.[StudentCTEProgramAssociation_DocumentId] IS NOT NULL AND del.[StudentCTEProgramAssociation_DocumentId] IS NULL)) OR (i.[ParticipationStatusDescriptor_DescriptorId] <> del.[ParticipationStatusDescriptor_DescriptorId] OR (i.[ParticipationStatusDescriptor_DescriptorId] IS NULL AND del.[ParticipationStatusDescriptor_DescriptorId] IS NOT NULL) OR (i.[ParticipationStatusDescriptor_DescriptorId] IS NOT NULL AND del.[ParticipationStatusDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[DesignatedBy] AS varbinary(max)) <> CAST(del.[DesignatedBy] AS varbinary(max)) OR (i.[DesignatedBy] IS NULL AND del.[DesignatedBy] IS NOT NULL) OR (i.[DesignatedBy] IS NOT NULL AND del.[DesignatedBy] IS NULL)) OR (i.[StatusBeginDate] <> del.[StatusBeginDate] OR (i.[StatusBeginDate] IS NULL AND del.[StatusBeginDate] IS NOT NULL) OR (i.[StatusBeginDate] IS NOT NULL AND del.[StatusBeginDate] IS NULL)) OR (i.[StatusEndDate] <> del.[StatusEndDate] OR (i.[StatusEndDate] IS NULL AND del.[StatusEndDate] IS NOT NULL) OR (i.[StatusEndDate] IS NOT NULL AND del.[StatusEndDate] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
