CREATE OR ALTER TRIGGER [edfi].[TR_StudentCohortAssociation_ReferentialIdentity]
ON [edfi].[StudentCohortAssociation]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 290;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiStudentCohortAssociation' AS nvarchar(max)) + N'$.beginDate=' + CONVERT(nvarchar(10), i.[BeginDate], 23) + N'#' + N'$.cohortReference.cohortIdentifier=' + i.[Cohort_CohortIdentifier] + N'#' + N'$.cohortReference.educationOrganizationId=' + CAST(i.[Cohort_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 290
        FROM inserted i;
    END
    ELSE IF (UPDATE([BeginDate]) OR UPDATE([Cohort_CohortIdentifier]) OR UPDATE([Cohort_EducationOrganizationId]) OR UPDATE([Student_StudentUniqueId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[BeginDate] <> d.[BeginDate] OR (i.[BeginDate] IS NULL AND d.[BeginDate] IS NOT NULL) OR (i.[BeginDate] IS NOT NULL AND d.[BeginDate] IS NULL)) OR (CAST(i.[Cohort_CohortIdentifier] AS varbinary(max)) <> CAST(d.[Cohort_CohortIdentifier] AS varbinary(max)) OR (i.[Cohort_CohortIdentifier] IS NULL AND d.[Cohort_CohortIdentifier] IS NOT NULL) OR (i.[Cohort_CohortIdentifier] IS NOT NULL AND d.[Cohort_CohortIdentifier] IS NULL)) OR (i.[Cohort_EducationOrganizationId] <> d.[Cohort_EducationOrganizationId] OR (i.[Cohort_EducationOrganizationId] IS NULL AND d.[Cohort_EducationOrganizationId] IS NOT NULL) OR (i.[Cohort_EducationOrganizationId] IS NOT NULL AND d.[Cohort_EducationOrganizationId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(d.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND d.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND d.[Student_StudentUniqueId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 290;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiStudentCohortAssociation' AS nvarchar(max)) + N'$.beginDate=' + CONVERT(nvarchar(10), i.[BeginDate], 23) + N'#' + N'$.cohortReference.cohortIdentifier=' + i.[Cohort_CohortIdentifier] + N'#' + N'$.cohortReference.educationOrganizationId=' + CAST(i.[Cohort_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 290
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_StudentCohortAssociation_Stamp]
ON [edfi].[StudentCohortAssociation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[Cohort_DocumentId] <> del.[Cohort_DocumentId] OR (i.[Cohort_DocumentId] IS NULL AND del.[Cohort_DocumentId] IS NOT NULL) OR (i.[Cohort_DocumentId] IS NOT NULL AND del.[Cohort_DocumentId] IS NULL)) OR (CAST(i.[Cohort_CohortIdentifier] AS varbinary(max)) <> CAST(del.[Cohort_CohortIdentifier] AS varbinary(max)) OR (i.[Cohort_CohortIdentifier] IS NULL AND del.[Cohort_CohortIdentifier] IS NOT NULL) OR (i.[Cohort_CohortIdentifier] IS NOT NULL AND del.[Cohort_CohortIdentifier] IS NULL)) OR (i.[Cohort_EducationOrganizationId] <> del.[Cohort_EducationOrganizationId] OR (i.[Cohort_EducationOrganizationId] IS NULL AND del.[Cohort_EducationOrganizationId] IS NOT NULL) OR (i.[Cohort_EducationOrganizationId] IS NOT NULL AND del.[Cohort_EducationOrganizationId] IS NULL)) OR (i.[Student_DocumentId] <> del.[Student_DocumentId] OR (i.[Student_DocumentId] IS NULL AND del.[Student_DocumentId] IS NOT NULL) OR (i.[Student_DocumentId] IS NOT NULL AND del.[Student_DocumentId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL)) OR (i.[BeginDate] <> del.[BeginDate] OR (i.[BeginDate] IS NULL AND del.[BeginDate] IS NOT NULL) OR (i.[BeginDate] IS NOT NULL AND del.[BeginDate] IS NULL)) OR (i.[EndDate] <> del.[EndDate] OR (i.[EndDate] IS NULL AND del.[EndDate] IS NOT NULL) OR (i.[EndDate] IS NOT NULL AND del.[EndDate] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[StudentCohortAssociation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[StudentCohortAssociation] (
            [OldBeginDate],
            [OldCohort_CohortIdentifier],
            [OldCohort_EducationOrganizationId],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[BeginDate],
            del.[Cohort_CohortIdentifier],
            del.[Cohort_EducationOrganizationId],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [edfi].[Student] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Student_DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[BeginDate] <> del.[BeginDate] OR (i.[BeginDate] IS NULL AND del.[BeginDate] IS NOT NULL) OR (i.[BeginDate] IS NOT NULL AND del.[BeginDate] IS NULL)) OR (CAST(i.[Cohort_CohortIdentifier] AS varbinary(max)) <> CAST(del.[Cohort_CohortIdentifier] AS varbinary(max)) OR (i.[Cohort_CohortIdentifier] IS NULL AND del.[Cohort_CohortIdentifier] IS NOT NULL) OR (i.[Cohort_CohortIdentifier] IS NOT NULL AND del.[Cohort_CohortIdentifier] IS NULL)) OR (i.[Cohort_EducationOrganizationId] <> del.[Cohort_EducationOrganizationId] OR (i.[Cohort_EducationOrganizationId] IS NULL AND del.[Cohort_EducationOrganizationId] IS NOT NULL) OR (i.[Cohort_EducationOrganizationId] IS NOT NULL AND del.[Cohort_EducationOrganizationId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[StudentCohortAssociation] (
            [OldBeginDate],
            [OldCohort_CohortIdentifier],
            [OldCohort_EducationOrganizationId],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [NewBeginDate],
            [NewCohort_CohortIdentifier],
            [NewCohort_EducationOrganizationId],
            [NewStudent_StudentUniqueId],
            [NewStudent_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[BeginDate],
            del.[Cohort_CohortIdentifier],
            del.[Cohort_EducationOrganizationId],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            i.[BeginDate],
            i.[Cohort_CohortIdentifier],
            i.[Cohort_EducationOrganizationId],
            i.[Student_StudentUniqueId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [edfi].[Student] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Student_DocumentId]
        INNER JOIN [edfi].[Student] newPj0s0 ON newPj0s0.[DocumentId] = i.[Student_DocumentId];
    END
END;
GO

