Association_SectionIdentifier] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NULL)) OR (CAST(i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NULL)) OR (CAST(i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NULL))
