_LocalCourseCode] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_LocalCourseCode] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_LocalCourseCode] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_LocalCourseCode] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_LocalCourseCode] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_LocalCourseCode] IS NULL)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] <> del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolId] IS NULL)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] <> del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SchoolYear] IS NULL)) OR (CAST(i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SectionIdentifier] IS NULL)) OR (CAST(i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_SessionName] IS NULL)) OR (CAST(i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] AS varbinary(max)) <> CAST(del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] AS varbinary(max)) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NOT NULL) OR (i.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NOT NULL AND del.[StudentCompetencyObjectiveSectionOrProgramChoiceStudentSectionAssociation_StudentUniqueId] IS NULL))
