CREATE OR ALTER TRIGGER [edfi].[TR_StudentContactAssociation_ReferentialIdentity]
ON [edfi].[StudentContactAssociation]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 292;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiStudentContactAssociation' AS nvarchar(max)) + N'$.contactReference.contactUniqueId=' + i.[Contact_ContactUniqueId] + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 292
        FROM inserted i;
    END
    ELSE IF (UPDATE([Contact_ContactUniqueId]) OR UPDATE([Student_StudentUniqueId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Contact_ContactUniqueId] AS varbinary(max)) <> CAST(d.[Contact_ContactUniqueId] AS varbinary(max)) OR (i.[Contact_ContactUniqueId] IS NULL AND d.[Contact_ContactUniqueId] IS NOT NULL) OR (i.[Contact_ContactUniqueId] IS NOT NULL AND d.[Contact_ContactUniqueId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(d.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND d.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND d.[Student_StudentUniqueId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 292;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiStudentContactAssociation' AS nvarchar(max)) + N'$.contactReference.contactUniqueId=' + i.[Contact_ContactUniqueId] + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 292
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_StudentContactAssociation_Stamp]
ON [edfi].[StudentContactAssociation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[Contact_DocumentId] <> del.[Contact_DocumentId] OR (i.[Contact_DocumentId] IS NULL AND del.[Contact_DocumentId] IS NOT NULL) OR (i.[Contact_DocumentId] IS NOT NULL AND del.[Contact_DocumentId] IS NULL)) OR (CAST(i.[Contact_ContactUniqueId] AS varbinary(max)) <> CAST(del.[Contact_ContactUniqueId] AS varbinary(max)) OR (i.[Contact_ContactUniqueId] IS NULL AND del.[Contact_ContactUniqueId] IS NOT NULL) OR (i.[Contact_ContactUniqueId] IS NOT NULL AND del.[Contact_ContactUniqueId] IS NULL)) OR (i.[Student_DocumentId] <> del.[Student_DocumentId] OR (i.[Student_DocumentId] IS NULL AND del.[Student_DocumentId] IS NOT NULL) OR (i.[Student_DocumentId] IS NOT NULL AND del.[Student_DocumentId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL)) OR (i.[RelationDescriptor_DescriptorId] <> del.[RelationDescriptor_DescriptorId] OR (i.[RelationDescriptor_DescriptorId] IS NULL AND del.[RelationDescriptor_DescriptorId] IS NOT NULL) OR (i.[RelationDescriptor_DescriptorId] IS NOT NULL AND del.[RelationDescriptor_DescriptorId] IS NULL)) OR (i.[ContactPriority] <> del.[ContactPriority] OR (i.[ContactPriority] IS NULL AND del.[ContactPriority] IS NOT NULL) OR (i.[ContactPriority] IS NOT NULL AND del.[ContactPriority] IS NULL)) OR (CAST(i.[ContactRestrictions] AS varbinary(max)) <> CAST(del.[ContactRestrictions] AS varbinary(max)) OR (i.[ContactRestrictions] IS NULL AND del.[ContactRestrictions] IS NOT NULL) OR (i.[ContactRestrictions] IS NOT NULL AND del.[ContactRestrictions] IS NULL)) OR (i.[EmergencyContactStatus] <> del.[EmergencyContactStatus] OR (i.[EmergencyContactStatus] IS NULL AND del.[EmergencyContactStatus] IS NOT NULL) OR (i.[EmergencyContactStatus] IS NOT NULL AND del.[EmergencyContactStatus] IS NULL)) OR (i.[LegalGuardian] <> del.[LegalGuardian] OR (i.[LegalGuardian] IS NULL AND del.[LegalGuardian] IS NOT NULL) OR (i.[LegalGuardian] IS NOT NULL AND del.[LegalGuardian] IS NULL)) OR (i.[LivesWith] <> del.[LivesWith] OR (i.[LivesWith] IS NULL AND del.[LivesWith] IS NOT NULL) OR (i.[LivesWith] IS NOT NULL AND del.[LivesWith] IS NULL)) OR (i.[PrimaryContactStatus] <> del.[PrimaryContactStatus] OR (i.[PrimaryContactStatus] IS NULL AND del.[PrimaryContactStatus] IS NOT NULL) OR (i.[PrimaryContactStatus] IS NOT NULL AND del.[PrimaryContactStatus] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[StudentContactAssociation] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[StudentContactAssociation] (
            [OldContact_ContactUniqueId],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [OldContact_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Contact_ContactUniqueId],
            del.[Student_StudentUniqueId],
            oldPj1s0.[DocumentId],
            oldPj0s0.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [edfi].[Contact] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Contact_DocumentId]
        INNER JOIN [edfi].[Student] oldPj1s0 ON oldPj1s0.[DocumentId] = del.[Student_DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Contact_ContactUniqueId] AS varbinary(max)) <> CAST(del.[Contact_ContactUniqueId] AS varbinary(max)) OR (i.[Contact_ContactUniqueId] IS NULL AND del.[Contact_ContactUniqueId] IS NOT NULL) OR (i.[Contact_ContactUniqueId] IS NOT NULL AND del.[Contact_ContactUniqueId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[StudentContactAssociation] (
            [OldContact_ContactUniqueId],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [OldContact_DocumentId],
            [NewContact_ContactUniqueId],
            [NewStudent_StudentUniqueId],
            [NewStudent_DocumentId],
            [NewContact_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Contact_ContactUniqueId],
            del.[Student_StudentUniqueId],
            oldPj1s0.[DocumentId],
            oldPj0s0.[DocumentId],
            i.[Contact_ContactUniqueId],
            i.[Student_StudentUniqueId],
            newPj1s0.[DocumentId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [edfi].[Contact] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Contact_DocumentId]
        INNER JOIN [edfi].[Student] oldPj1s0 ON oldPj1s0.[DocumentId] = del.[Student_DocumentId]
        INNER JOIN [edfi].[Contact] newPj0s0 ON newPj0s0.[DocumentId] = i.[Contact_DocumentId]
        INNER JOIN [edfi].[Student] newPj1s0 ON newPj1s0.[DocumentId] = i.[Student_DocumentId];
    END
END;
