            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            i.[GradebookEntry_GradebookEntryIdentifier],
            i.[GradebookEntry_Namespace],
            i.[Student_StudentUniqueId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
