            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [NewIntervention_EducationOrganizationId],
            [NewIntervention_InterventionIdentificationCode],
            [NewStudent_StudentUniqueId],
            [NewStudent_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
