            del.[Intervention_InterventionIdentificationCode],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            i.[Intervention_EducationOrganizationId],
            i.[Intervention_InterventionIdentificationCode],
            i.[Student_StudentUniqueId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
