CREATE OR ALTER TRIGGER [edfi].[TR_StudentInterventionAttendanceEvent_Stamp]
ON [edfi].[StudentInterventionAttendanceEvent]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (i.[Intervention_DocumentId] <> del.[Intervention_DocumentId] OR (i.[Intervention_DocumentId] IS NULL AND del.[Intervention_DocumentId] IS NOT NULL) OR (i.[Intervention_DocumentId] IS NOT NULL AND del.[Intervention_DocumentId] IS NULL)) OR (i.[Intervention_EducationOrganizationId] <> del.[Intervention_EducationOrganizationId] OR (i.[Intervention_EducationOrganizationId] IS NULL AND del.[Intervention_EducationOrganizationId] IS NOT NULL) OR (i.[Intervention_EducationOrganizationId] IS NOT NULL AND del.[Intervention_EducationOrganizationId] IS NULL)) OR (CAST(i.[Intervention_InterventionIdentificationCode] AS varbinary(max)) <> CAST(del.[Intervention_InterventionIdentificationCode] AS varbinary(max)) OR (i.[Intervention_InterventionIdentificationCode] IS NULL AND del.[Intervention_InterventionIdentificationCode] IS NOT NULL) OR (i.[Intervention_InterventionIdentificationCode] IS NOT NULL AND del.[Intervention_InterventionIdentificationCode] IS NULL)) OR (i.[Student_DocumentId] <> del.[Student_DocumentId] OR (i.[Student_DocumentId] IS NULL AND del.[Student_DocumentId] IS NOT NULL) OR (i.[Student_DocumentId] IS NOT NULL AND del.[Student_DocumentId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL)) OR (i.[AttendanceEventCategoryDescriptor_DescriptorId] <> del.[AttendanceEventCategoryDescriptor_DescriptorId] OR (i.[AttendanceEventCategoryDescriptor_DescriptorId] IS NULL AND del.[AttendanceEventCategoryDescriptor_DescriptorId] IS NOT NULL) OR (i.[AttendanceEventCategoryDescriptor_DescriptorId] IS NOT NULL AND del.[AttendanceEventCategoryDescriptor_DescriptorId] IS NULL)) OR (i.[EducationalEnvironmentDescriptor_DescriptorId] <> del.[EducationalEnvironmentDescriptor_DescriptorId] OR (i.[EducationalEnvironmentDescriptor_DescriptorId] IS NULL AND del.[EducationalEnvironmentDescriptor_DescriptorId] IS NOT NULL) OR (i.[EducationalEnvironmentDescriptor_DescriptorId] IS NOT NULL AND del.[EducationalEnvironmentDescriptor_DescriptorId] IS NULL)) OR (CAST(i.[AttendanceEventReason] AS varbinary(max)) <> CAST(del.[AttendanceEventReason] AS varbinary(max)) OR (i.[AttendanceEventReason] IS NULL AND del.[AttendanceEventReason] IS NOT NULL) OR (i.[AttendanceEventReason] IS NOT NULL AND del.[AttendanceEventReason] IS NULL)) OR (i.[EventDate] <> del.[EventDate] OR (i.[EventDate] IS NULL AND del.[EventDate] IS NOT NULL) OR (i.[EventDate] IS NOT NULL AND del.[EventDate] IS NULL)) OR (i.[EventDuration] <> del.[EventDuration] OR (i.[EventDuration] IS NULL AND del.[EventDuration] IS NOT NULL) OR (i.[EventDuration] IS NOT NULL AND del.[EventDuration] IS NULL)) OR (i.[InterventionDuration] <> del.[InterventionDuration] OR (i.[InterventionDuration] IS NULL AND del.[InterventionDuration] IS NOT NULL) OR (i.[InterventionDuration] IS NOT NULL AND del.[InterventionDuration] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[StudentInterventionAttendanceEvent] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[StudentInterventionAttendanceEvent] (
            [OldAttendanceEventCategoryDescriptor_Namespace],
            [OldAttendanceEventCategoryDescriptor_CodeValue],
            [OldEventDate],
            [OldIntervention_EducationOrganizationId],
            [OldIntervention_InterventionIdentificationCode],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[EventDate],
            del.[Intervention_EducationOrganizationId],
            del.[Intervention_InterventionIdentificationCode],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[AttendanceEventCategoryDescriptor_DescriptorId]
        INNER JOIN [edfi].[Student] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Student_DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (i.[AttendanceEventCategoryDescriptor_DescriptorId] <> del.[AttendanceEventCategoryDescriptor_DescriptorId] OR (i.[AttendanceEventCategoryDescriptor_DescriptorId] IS NULL AND del.[AttendanceEventCategoryDescriptor_DescriptorId] IS NOT NULL) OR (i.[AttendanceEventCategoryDescriptor_DescriptorId] IS NOT NULL AND del.[AttendanceEventCategoryDescriptor_DescriptorId] IS NULL)) OR (i.[EventDate] <> del.[EventDate] OR (i.[EventDate] IS NULL AND del.[EventDate] IS NOT NULL) OR (i.[EventDate] IS NOT NULL AND del.[EventDate] IS NULL)) OR (i.[Intervention_EducationOrganizationId] <> del.[Intervention_EducationOrganizationId] OR (i.[Intervention_EducationOrganizationId] IS NULL AND del.[Intervention_EducationOrganizationId] IS NOT NULL) OR (i.[Intervention_EducationOrganizationId] IS NOT NULL AND del.[Intervention_EducationOrganizationId] IS NULL)) OR (CAST(i.[Intervention_InterventionIdentificationCode] AS varbinary(max)) <> CAST(del.[Intervention_InterventionIdentificationCode] AS varbinary(max)) OR (i.[Intervention_InterventionIdentificationCode] IS NULL AND del.[Intervention_InterventionIdentificationCode] IS NOT NULL) OR (i.[Intervention_InterventionIdentificationCode] IS NOT NULL AND del.[Intervention_InterventionIdentificationCode] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL));
        INSERT INTO [tracked_changes_edfi].[StudentInterventionAttendanceEvent] (
            [OldAttendanceEventCategoryDescriptor_Namespace],
            [OldAttendanceEventCategoryDescriptor_CodeValue],
            [OldEventDate],
            [OldIntervention_EducationOrganizationId],
            [OldIntervention_InterventionIdentificationCode],
            [OldStudent_StudentUniqueId],
            [OldStudent_DocumentId],
            [NewAttendanceEventCategoryDescriptor_Namespace],
            [NewAttendanceEventCategoryDescriptor_CodeValue],
            [NewEventDate],
            [NewIntervention_EducationOrganizationId],
            [NewIntervention_InterventionIdentificationCode],
            [NewStudent_StudentUniqueId],
            [NewStudent_DocumentId],
            [Id],
            [ChangeVersion]
        )
        SELECT
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[EventDate],
            del.[Intervention_EducationOrganizationId],
            del.[Intervention_InterventionIdentificationCode],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[EventDate],
            i.[Intervention_EducationOrganizationId],
            i.[Intervention_InterventionIdentificationCode],
            i.[Student_StudentUniqueId],
            newPj0s0.[DocumentId],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Descriptor] oldDj0 ON oldDj0.[DocumentId] = del.[AttendanceEventCategoryDescriptor_DescriptorId]
        INNER JOIN [edfi].[Student] oldPj0s0 ON oldPj0s0.[DocumentId] = del.[Student_DocumentId]
        INNER JOIN [dms].[Descriptor] newDj0 ON newDj0.[DocumentId] = i.[AttendanceEventCategoryDescriptor_DescriptorId]
        INNER JOIN [edfi].[Student] newPj0s0 ON newPj0s0.[DocumentId] = i.[Student_DocumentId];
    END
END;
