            del.[EventDate],
            del.[ProgramProgram_EducationOrganizationId],
            del.[ProgramProgram_ProgramName],
            oldDj1.[Namespace],
            oldDj1.[CodeValue],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            newDj0.[Namespace],
            newDj0.[CodeValue],
            i.[EducationOrganization_EducationOrganizationId],
            i.[EventDate],
