        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[StudentSchoolFoodServiceProgramAssociation_DocumentId] <> del.[StudentSchoolFoodServiceProgramAssociation_DocumentId] OR (i.[StudentSchoolFoodServiceProgramAssociation_DocumentId] IS NULL AND del.[StudentSchoolFoodServiceProgramAssociation_DocumentId] IS NOT NULL) OR (i.[StudentSchoolFoodServiceProgramAssociation_DocumentId] IS NOT NULL AND del.[StudentSchoolFoodServiceProgramAssociation_DocumentId] IS NULL)) OR (i.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] <> del.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] OR (i.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] IS NULL AND del.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] IS NOT NULL) OR (i.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] IS NOT NULL AND del.[SchoolFoodServiceProgramServiceDescriptor_DescriptorId] IS NULL)) OR (i.[PrimaryIndicator] <> del.[PrimaryIndicator] OR (i.[PrimaryIndicator] IS NULL AND del.[PrimaryIndicator] IS NOT NULL) OR (i.[PrimaryIndicator] IS NOT NULL AND del.[PrimaryIndicator] IS NULL)) OR (i.[ServiceBeginDate] <> del.[ServiceBeginDate] OR (i.[ServiceBeginDate] IS NULL AND del.[ServiceBeginDate] IS NOT NULL) OR (i.[ServiceBeginDate] IS NOT NULL AND del.[ServiceBeginDate] IS NULL)) OR (i.[ServiceEndDate] <> del.[ServiceEndDate] OR (i.[ServiceEndDate] IS NULL AND del.[ServiceEndDate] IS NOT NULL) OR (i.[ServiceEndDate] IS NOT NULL AND del.[ServiceEndDate] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
