    INNER JOIN [edfi].[StudentSection504ProgramAssociation] stampTarget ON stampTarget.[DocumentId] = a.[StudentSection504ProgramAssociation_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
