CREATE OR ALTER TRIGGER [edfi].[TR_StudentSectionAttendanceEventClassPeriod_Stamp]
ON [edfi].[StudentSectionAttendanceEventClassPeriod]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    ;WITH affectedDocs AS (
        SELECT i.[StudentSectionAttendanceEvent_DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[CollectionItemId] = i.[CollectionItemId]
        WHERE del.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[StudentSectionAttendanceEvent_DocumentId] <> del.[StudentSectionAttendanceEvent_DocumentId] OR (i.[StudentSectionAttendanceEvent_DocumentId] IS NULL AND del.[StudentSectionAttendanceEvent_DocumentId] IS NOT NULL) OR (i.[StudentSectionAttendanceEvent_DocumentId] IS NOT NULL AND del.[StudentSectionAttendanceEvent_DocumentId] IS NULL)) OR (i.[ClassPeriod_DocumentId] <> del.[ClassPeriod_DocumentId] OR (i.[ClassPeriod_DocumentId] IS NULL AND del.[ClassPeriod_DocumentId] IS NOT NULL) OR (i.[ClassPeriod_DocumentId] IS NOT NULL AND del.[ClassPeriod_DocumentId] IS NULL)) OR (CAST(i.[ClassPeriod_ClassPeriodName] AS varbinary(max)) <> CAST(del.[ClassPeriod_ClassPeriodName] AS varbinary(max)) OR (i.[ClassPeriod_ClassPeriodName] IS NULL AND del.[ClassPeriod_ClassPeriodName] IS NOT NULL) OR (i.[ClassPeriod_ClassPeriodName] IS NOT NULL AND del.[ClassPeriod_ClassPeriodName] IS NULL)) OR (i.[ClassPeriod_SchoolId] <> del.[ClassPeriod_SchoolId] OR (i.[ClassPeriod_SchoolId] IS NULL AND del.[ClassPeriod_SchoolId] IS NOT NULL) OR (i.[ClassPeriod_SchoolId] IS NOT NULL AND del.[ClassPeriod_SchoolId] IS NULL))
        UNION
        SELECT del.[StudentSectionAttendanceEvent_DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[CollectionItemId] = del.[CollectionItemId]
        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[StudentSectionAttendanceEvent_DocumentId] <> del.[StudentSectionAttendanceEvent_DocumentId] OR (i.[StudentSectionAttendanceEvent_DocumentId] IS NULL AND del.[StudentSectionAttendanceEvent_DocumentId] IS NOT NULL) OR (i.[StudentSectionAttendanceEvent_DocumentId] IS NOT NULL AND del.[StudentSectionAttendanceEvent_DocumentId] IS NULL)) OR (i.[ClassPeriod_DocumentId] <> del.[ClassPeriod_DocumentId] OR (i.[ClassPeriod_DocumentId] IS NULL AND del.[ClassPeriod_DocumentId] IS NOT NULL) OR (i.[ClassPeriod_DocumentId] IS NOT NULL AND del.[ClassPeriod_DocumentId] IS NULL)) OR (CAST(i.[ClassPeriod_ClassPeriodName] AS varbinary(max)) <> CAST(del.[ClassPeriod_ClassPeriodName] AS varbinary(max)) OR (i.[ClassPeriod_ClassPeriodName] IS NULL AND del.[ClassPeriod_ClassPeriodName] IS NOT NULL) OR (i.[ClassPeriod_ClassPeriodName] IS NOT NULL AND del.[ClassPeriod_ClassPeriodName] IS NULL)) OR (i.[ClassPeriod_SchoolId] <> del.[ClassPeriod_SchoolId] OR (i.[ClassPeriod_SchoolId] IS NULL AND del.[ClassPeriod_SchoolId] IS NOT NULL) OR (i.[ClassPeriod_SchoolId] IS NOT NULL AND del.[ClassPeriod_SchoolId] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[StudentSectionAttendanceEvent_DocumentId]
    INNER JOIN [edfi].[StudentSectionAttendanceEvent] stampTarget ON stampTarget.[DocumentId] = a.[StudentSectionAttendanceEvent_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[StudentSectionAttendanceEvent] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
