CREATE OR ALTER TRIGGER [edfi].[TR_SurveyQuestionResponse_ReferentialIdentity]
ON [edfi].[SurveyQuestionResponse]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 328;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiSurveyQuestionResponse' AS nvarchar(max)) + N'$.surveyQuestionReference.namespace=' + i.[SurveyQuestion_Namespace] + N'#' + N'$.surveyQuestionReference.questionCode=' + i.[SurveyQuestion_QuestionCode] + N'#' + N'$.surveyQuestionReference.surveyIdentifier=' + i.[SurveyQuestion_SurveyIdentifier] + N'#' + N'$.surveyResponseReference.namespace=' + i.[SurveyResponse_Namespace] + N'#' + N'$.surveyResponseReference.surveyIdentifier=' + i.[SurveyResponse_SurveyIdentifier] + N'#' + N'$.surveyResponseReference.surveyResponseIdentifier=' + i.[SurveyResponse_SurveyResponseIdentifier]), i.[DocumentId], 328
        FROM inserted i;
    END
    ELSE IF (UPDATE([Namespace_Unified]) OR UPDATE([SurveyQuestion_QuestionCode]) OR UPDATE([SurveyIdentifier_Unified]) OR UPDATE([SurveyResponse_SurveyResponseIdentifier]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(d.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND d.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND d.[Namespace_Unified] IS NULL)) OR (CAST(i.[SurveyQuestion_QuestionCode] AS varbinary(max)) <> CAST(d.[SurveyQuestion_QuestionCode] AS varbinary(max)) OR (i.[SurveyQuestion_QuestionCode] IS NULL AND d.[SurveyQuestion_QuestionCode] IS NOT NULL) OR (i.[SurveyQuestion_QuestionCode] IS NOT NULL AND d.[SurveyQuestion_QuestionCode] IS NULL)) OR (CAST(i.[SurveyIdentifier_Unified] AS varbinary(max)) <> CAST(d.[SurveyIdentifier_Unified] AS varbinary(max)) OR (i.[SurveyIdentifier_Unified] IS NULL AND d.[SurveyIdentifier_Unified] IS NOT NULL) OR (i.[SurveyIdentifier_Unified] IS NOT NULL AND d.[SurveyIdentifier_Unified] IS NULL)) OR (CAST(i.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) <> CAST(d.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NULL AND d.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL AND d.[SurveyResponse_SurveyResponseIdentifier] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 328;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'Ed-FiSurveyQuestionResponse' AS nvarchar(max)) + N'$.surveyQuestionReference.namespace=' + i.[SurveyQuestion_Namespace] + N'#' + N'$.surveyQuestionReference.questionCode=' + i.[SurveyQuestion_QuestionCode] + N'#' + N'$.surveyQuestionReference.surveyIdentifier=' + i.[SurveyQuestion_SurveyIdentifier] + N'#' + N'$.surveyResponseReference.namespace=' + i.[SurveyResponse_Namespace] + N'#' + N'$.surveyResponseReference.surveyIdentifier=' + i.[SurveyResponse_SurveyIdentifier] + N'#' + N'$.surveyResponseReference.surveyResponseIdentifier=' + i.[SurveyResponse_SurveyResponseIdentifier]), i.[DocumentId], 328
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
GO

CREATE OR ALTER TRIGGER [edfi].[TR_SurveyQuestionResponse_Stamp]
ON [edfi].[SurveyQuestionResponse]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @stamped TABLE (
        [DocumentId] bigint NOT NULL PRIMARY KEY,
        [ContentVersion] bigint NOT NULL,
        [ContentLastModifiedAt] datetime2(7) NOT NULL
    );
    INSERT INTO @stamped ([DocumentId], [ContentVersion], [ContentLastModifiedAt])
    SELECT d.[DocumentId], d.[ContentVersion], d.[ContentLastModifiedAt]
    FROM [dms].[Document] d
    INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
    LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
    WHERE del.[DocumentId] IS NULL;
    ;WITH affectedDocs AS (
        SELECT i.[DocumentId]
        FROM inserted i
        LEFT JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE del.[DocumentId] IS NOT NULL AND ((i.[DocumentId] <> del.[DocumentId] OR (i.[DocumentId] IS NULL AND del.[DocumentId] IS NOT NULL) OR (i.[DocumentId] IS NOT NULL AND del.[DocumentId] IS NULL)) OR (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(del.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND del.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND del.[Namespace_Unified] IS NULL)) OR (CAST(i.[SurveyIdentifier_Unified] AS varbinary(max)) <> CAST(del.[SurveyIdentifier_Unified] AS varbinary(max)) OR (i.[SurveyIdentifier_Unified] IS NULL AND del.[SurveyIdentifier_Unified] IS NOT NULL) OR (i.[SurveyIdentifier_Unified] IS NOT NULL AND del.[SurveyIdentifier_Unified] IS NULL)) OR (i.[SurveyQuestion_DocumentId] <> del.[SurveyQuestion_DocumentId] OR (i.[SurveyQuestion_DocumentId] IS NULL AND del.[SurveyQuestion_DocumentId] IS NOT NULL) OR (i.[SurveyQuestion_DocumentId] IS NOT NULL AND del.[SurveyQuestion_DocumentId] IS NULL)) OR (CAST(i.[SurveyQuestion_QuestionCode] AS varbinary(max)) <> CAST(del.[SurveyQuestion_QuestionCode] AS varbinary(max)) OR (i.[SurveyQuestion_QuestionCode] IS NULL AND del.[SurveyQuestion_QuestionCode] IS NOT NULL) OR (i.[SurveyQuestion_QuestionCode] IS NOT NULL AND del.[SurveyQuestion_QuestionCode] IS NULL)) OR (i.[SurveyResponse_DocumentId] <> del.[SurveyResponse_DocumentId] OR (i.[SurveyResponse_DocumentId] IS NULL AND del.[SurveyResponse_DocumentId] IS NOT NULL) OR (i.[SurveyResponse_DocumentId] IS NOT NULL AND del.[SurveyResponse_DocumentId] IS NULL)) OR (CAST(i.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) <> CAST(del.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NULL AND del.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL AND del.[SurveyResponse_SurveyResponseIdentifier] IS NULL)) OR (CAST(i.[Comment] AS varbinary(max)) <> CAST(del.[Comment] AS varbinary(max)) OR (i.[Comment] IS NULL AND del.[Comment] IS NOT NULL) OR (i.[Comment] IS NOT NULL AND del.[Comment] IS NULL)) OR (i.[NoResponse] <> del.[NoResponse] OR (i.[NoResponse] IS NULL AND del.[NoResponse] IS NOT NULL) OR (i.[NoResponse] IS NOT NULL AND del.[NoResponse] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[SurveyQuestionResponse] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO [tracked_changes_edfi].[SurveyQuestionResponse] (
            [OldNamespace_Unified],
            [OldSurveyQuestion_QuestionCode],
            [OldSurveyIdentifier_Unified],
            [OldSurveyResponse_SurveyResponseIdentifier],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Namespace_Unified],
            del.[SurveyQuestion_QuestionCode],
            del.[SurveyIdentifier_Unified],
            del.[SurveyResponse_SurveyResponseIdentifier],
            doc.[DocumentUuid],
            doc.[ContentVersion]
        FROM deleted del
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = del.[DocumentId];
    END
    IF EXISTS (SELECT 1 FROM deleted) AND EXISTS (SELECT 1 FROM inserted)
    BEGIN
        DECLARE @identityChangedDocs TABLE ([DocumentId] bigint NOT NULL PRIMARY KEY, [ContentVersion] bigint NOT NULL);
        UPDATE d
        SET d.[IdentityVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[IdentityLastModifiedAt] = sysutcdatetime()
        OUTPUT inserted.[DocumentId], inserted.[ContentVersion] INTO @identityChangedDocs
        FROM [dms].[Document] d
        INNER JOIN inserted i ON d.[DocumentId] = i.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        WHERE (CAST(i.[Namespace_Unified] AS varbinary(max)) <> CAST(del.[Namespace_Unified] AS varbinary(max)) OR (i.[Namespace_Unified] IS NULL AND del.[Namespace_Unified] IS NOT NULL) OR (i.[Namespace_Unified] IS NOT NULL AND del.[Namespace_Unified] IS NULL)) OR (CAST(i.[SurveyQuestion_QuestionCode] AS varbinary(max)) <> CAST(del.[SurveyQuestion_QuestionCode] AS varbinary(max)) OR (i.[SurveyQuestion_QuestionCode] IS NULL AND del.[SurveyQuestion_QuestionCode] IS NOT NULL) OR (i.[SurveyQuestion_QuestionCode] IS NOT NULL AND del.[SurveyQuestion_QuestionCode] IS NULL)) OR (CAST(i.[SurveyIdentifier_Unified] AS varbinary(max)) <> CAST(del.[SurveyIdentifier_Unified] AS varbinary(max)) OR (i.[SurveyIdentifier_Unified] IS NULL AND del.[SurveyIdentifier_Unified] IS NOT NULL) OR (i.[SurveyIdentifier_Unified] IS NOT NULL AND del.[SurveyIdentifier_Unified] IS NULL)) OR (CAST(i.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) <> CAST(del.[SurveyResponse_SurveyResponseIdentifier] AS varbinary(max)) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NULL AND del.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL) OR (i.[SurveyResponse_SurveyResponseIdentifier] IS NOT NULL AND del.[SurveyResponse_SurveyResponseIdentifier] IS NULL));
        INSERT INTO [tracked_changes_edfi].[SurveyQuestionResponse] (
            [OldNamespace_Unified],
            [OldSurveyQuestion_QuestionCode],
            [OldSurveyIdentifier_Unified],
            [OldSurveyResponse_SurveyResponseIdentifier],
            [NewNamespace_Unified],
            [NewSurveyQuestion_QuestionCode],
            [NewSurveyIdentifier_Unified],
            [NewSurveyResponse_SurveyResponseIdentifier],
            [Id],
            [ChangeVersion]
        )
        SELECT
            del.[Namespace_Unified],
            del.[SurveyQuestion_QuestionCode],
            del.[SurveyIdentifier_Unified],
            del.[SurveyResponse_SurveyResponseIdentifier],
            i.[Namespace_Unified],
            i.[SurveyQuestion_QuestionCode],
            i.[SurveyIdentifier_Unified],
            i.[SurveyResponse_SurveyResponseIdentifier],
            doc.[DocumentUuid],
            idc.[ContentVersion]
        FROM @identityChangedDocs idc
        INNER JOIN inserted i ON i.[DocumentId] = idc.[DocumentId]
        INNER JOIN deleted del ON del.[DocumentId] = i.[DocumentId]
        INNER JOIN [dms].[Document] doc ON doc.[DocumentId] = i.[DocumentId];
    END
END;
GO

