        WHERE i.[CollectionItemId] IS NULL OR (i.[CollectionItemId] <> del.[CollectionItemId] OR (i.[CollectionItemId] IS NULL AND del.[CollectionItemId] IS NOT NULL) OR (i.[CollectionItemId] IS NOT NULL AND del.[CollectionItemId] IS NULL)) OR (i.[Ordinal] <> del.[Ordinal] OR (i.[Ordinal] IS NULL AND del.[Ordinal] IS NOT NULL) OR (i.[Ordinal] IS NOT NULL AND del.[Ordinal] IS NULL)) OR (i.[SurveyQuestionResponse_DocumentId] <> del.[SurveyQuestionResponse_DocumentId] OR (i.[SurveyQuestionResponse_DocumentId] IS NULL AND del.[SurveyQuestionResponse_DocumentId] IS NOT NULL) OR (i.[SurveyQuestionResponse_DocumentId] IS NOT NULL AND del.[SurveyQuestionResponse_DocumentId] IS NULL)) OR (i.[NumericResponse] <> del.[NumericResponse] OR (i.[NumericResponse] IS NULL AND del.[NumericResponse] IS NOT NULL) OR (i.[NumericResponse] IS NOT NULL AND del.[NumericResponse] IS NULL)) OR (i.[SurveyQuestionResponseValueIdentifier] <> del.[SurveyQuestionResponseValueIdentifier] OR (i.[SurveyQuestionResponseValueIdentifier] IS NULL AND del.[SurveyQuestionResponseValueIdentifier] IS NOT NULL) OR (i.[SurveyQuestionResponseValueIdentifier] IS NOT NULL AND del.[SurveyQuestionResponseValueIdentifier] IS NULL)) OR (CAST(i.[TextResponse] AS varbinary(max)) <> CAST(del.[TextResponse] AS varbinary(max)) OR (i.[TextResponse] IS NULL AND del.[TextResponse] IS NOT NULL) OR (i.[TextResponse] IS NOT NULL AND del.[TextResponse] IS NULL))
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[SurveyQuestionResponse_DocumentId]
    INNER JOIN [edfi].[SurveyQuestionResponse] stampTarget ON stampTarget.[DocumentId] = a.[SurveyQuestionResponse_DocumentId];
    IF EXISTS (SELECT 1 FROM @stamped)
    BEGIN
        UPDATE r
        SET r.[ContentVersion] = s.[ContentVersion],
            r.[ContentLastModifiedAt] = s.[ContentLastModifiedAt]
        FROM [edfi].[SurveyQuestionResponse] r
        INNER JOIN @stamped s ON s.[DocumentId] = r.[DocumentId];
    END
END;
