CREATE OR ALTER TRIGGER [edfi].[TR_SurveySectionResponseEducationOrganizationTargetAssociation_Stamp]
ON [edfi].[SurveySectionResponseEducationOrganizationTargetAssociation]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
