            del.[EducationOrganization_EducationOrganizationId],
            del.[ProgramProgram_EducationOrganizationId],
            del.[ProgramProgram_ProgramName],
            oldDj0.[Namespace],
            oldDj0.[CodeValue],
            del.[Student_StudentUniqueId],
            oldPj0s0.[DocumentId],
            doc.[DocumentUuid],
            doc.[ContentVersion]
