CREATE OR ALTER TRIGGER [sample].[TR_StudentGraduationPlanAssociation_ReferentialIdentity]
ON [sample].[StudentGraduationPlanAssociation]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM inserted) AND [ResourceKeyId] = 358;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'SampleStudentGraduationPlanAssociation' AS nvarchar(max)) + N'$.graduationPlanReference.educationOrganizationId=' + CAST(i.[GraduationPlan_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.graduationPlanReference.graduationPlanTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId])) + N'#' + N'$.graduationPlanReference.graduationSchoolYear=' + CAST(i.[GraduationPlan_GraduationSchoolYear] AS nvarchar(max)) + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 358
        FROM inserted i;
    END
    ELSE IF (UPDATE([GraduationPlan_EducationOrganizationId]) OR UPDATE([GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId]) OR UPDATE([GraduationPlan_GraduationSchoolYear]) OR UPDATE([Student_StudentUniqueId]))
    BEGIN
        DECLARE @changedDocs TABLE ([DocumentId] bigint NOT NULL);
        INSERT INTO @changedDocs ([DocumentId])
        SELECT i.[DocumentId]
        FROM inserted i INNER JOIN deleted d ON d.[DocumentId] = i.[DocumentId]
        WHERE (i.[GraduationPlan_EducationOrganizationId] <> d.[GraduationPlan_EducationOrganizationId] OR (i.[GraduationPlan_EducationOrganizationId] IS NULL AND d.[GraduationPlan_EducationOrganizationId] IS NOT NULL) OR (i.[GraduationPlan_EducationOrganizationId] IS NOT NULL AND d.[GraduationPlan_EducationOrganizationId] IS NULL)) OR (i.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] <> d.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] OR (i.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] IS NULL AND d.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] IS NOT NULL) OR (i.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] IS NOT NULL AND d.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId] IS NULL)) OR (i.[GraduationPlan_GraduationSchoolYear] <> d.[GraduationPlan_GraduationSchoolYear] OR (i.[GraduationPlan_GraduationSchoolYear] IS NULL AND d.[GraduationPlan_GraduationSchoolYear] IS NOT NULL) OR (i.[GraduationPlan_GraduationSchoolYear] IS NOT NULL AND d.[GraduationPlan_GraduationSchoolYear] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(d.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND d.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND d.[Student_StudentUniqueId] IS NULL));
        DELETE FROM [dms].[ReferentialIdentity]
        WHERE [DocumentId] IN (SELECT [DocumentId] FROM @changedDocs) AND [ResourceKeyId] = 358;
        INSERT INTO [dms].[ReferentialIdentity] ([ReferentialId], [DocumentId], [ResourceKeyId])
        SELECT [dms].[uuidv5]('edf1edf1-3df1-3df1-3df1-3df1edf1edf1', CAST(N'SampleStudentGraduationPlanAssociation' AS nvarchar(max)) + N'$.graduationPlanReference.educationOrganizationId=' + CAST(i.[GraduationPlan_EducationOrganizationId] AS nvarchar(max)) + N'#' + N'$.graduationPlanReference.graduationPlanTypeDescriptor=' + LOWER((SELECT descriptor.[Uri] FROM [dms].[Descriptor] descriptor WHERE descriptor.[DocumentId] = i.[GraduationPlan_GraduationPlanTypeDescriptor_DescriptorId])) + N'#' + N'$.graduationPlanReference.graduationSchoolYear=' + CAST(i.[GraduationPlan_GraduationSchoolYear] AS nvarchar(max)) + N'#' + N'$.studentReference.studentUniqueId=' + i.[Student_StudentUniqueId]), i.[DocumentId], 358
        FROM inserted i INNER JOIN @changedDocs cd ON cd.[DocumentId] = i.[DocumentId];
    END
END;
