 OR (i.[Student_DocumentId] <> del.[Student_DocumentId] OR (i.[Student_DocumentId] IS NULL AND del.[Student_DocumentId] IS NOT NULL) OR (i.[Student_DocumentId] IS NOT NULL AND del.[Student_DocumentId] IS NULL)) OR (CAST(i.[Student_StudentUniqueId] AS varbinary(max)) <> CAST(del.[Student_StudentUniqueId] AS varbinary(max)) OR (i.[Student_StudentUniqueId] IS NULL AND del.[Student_StudentUniqueId] IS NOT NULL) OR (i.[Student_StudentUniqueId] IS NOT NULL AND del.[Student_StudentUniqueId] IS NULL)) OR (i.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] <> del.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] OR (i.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] IS NULL AND del.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] IS NOT NULL) OR (i.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] IS NOT NULL AND del.[CteProgramServiceCteProgramServiceDescriptor_DescriptorId] IS NULL)) OR (i.[CommencementTime] <> del.[CommencementTime] OR (i.[CommencementTime] IS NULL AND del.[CommencementTime] IS NOT NULL) OR (i.[CommencementTime] IS NOT NULL AND del.[CommencementTime] IS NULL)) OR (CAST(i.[CteProgramServiceCipCode] AS varbinary(max)) <> CAST(del.[CteProgramServiceCipCode] AS varbinary(max)) OR (i.[CteProgramServiceCipCode] IS NULL AND del.[CteProgramServiceCipCode] IS NOT NULL) OR (i.[CteProgramServiceCipCode] IS NOT NULL AND del.[CteProgramServiceCipCode] IS NULL)) OR (i.[CteProgramServicePrimaryIndicator] <> del.[CteProgramServicePrimaryIndicator] OR (i.[CteProgramServicePrimaryIndicator] IS NULL AND del.[CteProgramServicePrimaryIndicator] IS NOT NULL) OR (i.[CteProgramServicePrimaryIndicator] IS NOT NULL AND del.[CteProgramServicePrimaryIndicator] IS NULL)) OR (i.[CteProgramServiceServiceBeginDate] <> del.[CteProgramServiceServiceBeginDate] OR (i.[CteProgramServiceServiceBeginDate] IS NULL AND del.[CteProgramServiceServiceBeginDate] IS NOT NULL) OR (i.[CteProgramServiceServiceBeginDate] IS NOT NULL AND del.[CteProgramServiceServiceBeginDate] IS NULL)) OR (i.[CteProgramServiceServiceEndDate] <> del.[CteProgramServiceServiceEndDate] OR (i.[CteProgramServiceServiceEndDate] IS NULL AND del.[CteProgramServiceServiceEndDate] IS NOT NULL) OR (i.[CteProgramServiceServiceEndDate] IS NOT NULL AND del.[CteProgramServiceServiceEndDate] IS NULL)) OR (i.[EffectiveDate] <> del.[EffectiveDate] OR (i.[EffectiveDate] IS NULL AND del.[EffectiveDate] IS NOT NULL) OR (i.[EffectiveDate] IS NOT NULL AND del.[EffectiveDate] IS NULL)) OR (i.[GraduationFee] <> del.[GraduationFee] OR (i.[GraduationFee] IS NULL AND del.[GraduationFee] IS NOT NULL) OR (i.[GraduationFee] IS NOT NULL AND del.[GraduationFee] IS NULL)) OR (CAST(i.[HighSchoolDuration] AS varbinary(max)) <> CAST(del.[HighSchoolDuration] AS varbinary(max)) OR (i.[HighSchoolDuration] IS NULL AND del.[HighSchoolDuration] IS NOT NULL) OR (i.[HighSchoolDuration] IS NOT NULL AND del.[HighSchoolDuration] IS NULL)) OR (i.[HoursPerWeek] <> del.[HoursPerWeek] OR (i.[HoursPerWeek] IS NULL AND del.[HoursPerWeek] IS NOT NULL) OR (i.[HoursPerWeek] IS NOT NULL AND del.[HoursPerWeek] IS NULL)) OR (i.[IsActivePlan] <> del.[IsActivePlan] OR (i.[IsActivePlan] IS NULL AND del.[IsActivePlan] IS NOT NULL) OR (i.[IsActivePlan] IS NOT NULL AND del.[IsActivePlan] IS NULL)) OR (i.[RequiredAttendance] <> del.[RequiredAttendance] OR (i.[RequiredAttendance] IS NULL AND del.[RequiredAttendance] IS NOT NULL) OR (i.[RequiredAttendance] IS NOT NULL AND del.[RequiredAttendance] IS NULL)) OR (i.[TargetGPA] <> del.[TargetGPA] OR (i.[TargetGPA] IS NULL AND del.[TargetGPA] IS NOT NULL) OR (i.[TargetGPA] IS NOT NULL AND del.[TargetGPA] IS NULL)))
        UNION ALL
        SELECT del.[DocumentId]
        FROM deleted del
        LEFT JOIN inserted i ON i.[DocumentId] = del.[DocumentId]
        WHERE i.[DocumentId] IS NULL
    )
    UPDATE d
    SET d.[ContentVersion] = NEXT VALUE FOR [dms].[ChangeVersionSequence], d.[ContentLastModifiedAt] = sysutcdatetime()
    OUTPUT inserted.[DocumentId], inserted.[ContentVersion], inserted.[ContentLastModifiedAt] INTO @stamped
    FROM [dms].[Document] d
    INNER JOIN affectedDocs a ON d.[DocumentId] = a.[DocumentId];
